insert into private.study_guides (guide, chunks, sha256) values ('study_guide_lag_bua125', 36, 'd40f56bea78aa01018bb165aac6e784d667cbe69dd0f5e88d5f86c093e67aa21');
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua125', 1, $study_guide${"guide":"study_guide_lag_bua125","code":"LAG-BUA125","courseId":"caf0ea5d-6cc0-5bd0-8719-c6f1a95ceec1","actor":"00000000-0000-4000-8000-000000000045","overview":{"itemId":"68eb5b98-cb47-5129-accb-b48684233052","create":true,"after":{"title":"Managerial Economics","body":"Every topic is examinable.","outcomes":["Explain managerial economics and the goals of managerial decisions in profit-seeking, non-profit and public organisations.","Apply opportunity cost to business decisions and tell accounting profit from economic profit.","Analyse market attractiveness and demand, calculate elasticities, and explain the product life cycle.","Describe forecasting types and methods and prepare simple forecasts.","Analyse short-run and long-run costs and their implications for managers.","Explain market segmentation, targeting and positioning.","Compare the types of business firm.","Compare market structures and how price and output are set in each."],"assessment":["The exam is objective (CBT), with some theory questions. Expect definitions, lists, applications to Nigerian businesses and short calculations.","Calculations come mainly from Topics 2, 3, 4, 5 and 8. Practise each worked example until you can do it quickly."]}},"retire":[],"notes":[{"kind":"note","itemId":"275f582a-3c36-5557-851f-8f34fedab618","sourceKey":"guide-topic:1","position":1,"payload":{"title":"Introduction to Managerial Economics and Managerial Decisions","body":"The definition, nature and scope of managerial economics; its micro and macro sides; the three business categories it serves; its goals and the decisions it guides; the objectives of firms, non-profits and the public sector (with computations); and the steps in decision making.","noteType":"guide_topic","number":1,"mustKnow":[{"text":"The definition, nature and scope of managerial economics; its micro and macro sides; the three business categories it serves; its goals and the decisions it guides; the objectives of firms, non-profits and the public sector (with computations); and the steps in decision making."}],"lessons":[{"number":"1.1","title":"Meaning and nature of managerial economics","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Managerial economics (ME):","bold":true},{"text":" the use of economic theories, concepts and models to make business decisions, irrespective of the type or category of organisation."}]},{"text":[{"text":"Second definition:","bold":true},{"text":" the application of economic tools to improve and enhance managers' decision making in businesses."}]},{"text":[{"text":"Why it is a subfield of economics:","bold":true},{"text":" it focuses on the production, distribution and consumption of goods and services in a system."}]},{"text":[{"text":"Where it applies:","bold":true},{"text":" profit-making organisations, non-profit-making organisations and the public sector (government activities that meet the needs of society). Not profit-making firms only."}]},{"text":[{"text":"Why it is strategic:","bold":true},{"text":" its application covers "},{"text":"both","bold":true},{"text":" microeconomic and macroeconomic concepts."}]},{"text":[{"text":"Managerial positions","bold":true},{"text":" are not limited to profit-making firms. In the public sector and non-profits they carry other titles: HoD, Minister, Commissioner, DG, Coordinator, Vice Chancellor, Provost, Dean."}]},{"text":[{"text":"Functions and operations:","bold":true},{"text":" using economic theories, models and concepts to analyse, solve and operationalise problems that arise in business decision making."}]}]},{"type":"paragraph","text":[{"text":"Nature of ME","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Applied and practical:","bold":true},{"text":" it aims to solve real decision problems of organisations. This is how it differs from traditional economic theory, which is more abstract."}]},{"text":[{"text":"Normative (prescriptive):","bold":true},{"text":" it says what managers "},{"text":"ought","bold":true},{"text":" to do to achieve their objectives, not just what happened."}]},{"text":[{"text":"Mainly micro, but also macro:","bold":true},{"text":" it deals with decision problems of the individual organisation while taking account of macroeconomic conditions (interest rates, exchange rates, government spending)."}]},{"text":[{"text":"A link (bridge):","bold":true},{"text":" it links traditional economic theory with the "},{"text":"decision sciences","bold":true},{"text":" (mathematics, statistics, econometrics)."}]},{"text":[{"text":"Pragmatic and quantitative:","bold":true},{"text":" it uses figures, models and forecasts."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Relationship with other disciplines:","bold":true},{"text":" economics supplies the theory (demand, cost, markets); "},{"text":"mathematics","bold":true},{"text":" supplies tools for optimisation; "},{"text":"statistics and econometrics","bold":true},{"text":" estimate demand and forecast; "},{"text":"accounting","bold":true},{"text":" supplies cost and revenue data; "},{"text":"operations research","bold":true},{"text":" supplies techniques such as linear programming; "},{"text":"management","bold":true},{"text":" supplies the organisational setting in which decisions are taken."}]},{"text":[{"text":"Role of the managerial economist:","bold":true},{"text":" forecasting demand, advising on pricing policy, analysing investment and expansion proposals, studying the external economic environment. Example: an economist at a Lagos cement company (think Dangote Cement) studies expected interest rates, exchange rates and government spending, then advises the board whether to build a new plant. That is analysing the external economic environment to guide decisions."}]},{"text":[{"text":"Traps:","bold":true},{"text":" ME is "},{"text":"not","bold":true},{"text":" monetary policy by a central bank, "},{"text":"not","bold":true},{"text":" $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua125', 2, $study_guide$financial accounting (recording transactions), "},{"text":"not","bold":true},{"text":" business law, and "},{"text":"not","bold":true},{"text":" motivating staff (that is management/organisational behaviour). Signing the statutory audit report is an auditor's job, not a managerial economist's."}]}]}]},{"number":"1.2","title":"Scope of managerial economics","mustKnow":[{"type":"table","header":[[{"text":"Microeconomic side"}],[{"text":"Macroeconomic side"}]],"rows":[[[{"text":"Demand and supply"}],[{"text":"Population and distribution"}]],[[{"text":"Production"}],[{"text":"Foreign exchange"}]],[[{"text":"Equilibrium"}],[{"text":"Interest rates"}]],[[{"text":"Opportunity cost"}],[{"text":"Output"}]],[[{"text":"Profit maximisation"}],[{"text":"Unemployment"}]],[[{"text":"Market competition"}],[{"text":"Distribution of income"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Microeconomics:","bold":true},{"text":" behaviour of individual units: households (consumers), firms and individual industries (e.g. the electronics industry)."}]},{"text":[{"text":"Macroeconomics:","bold":true},{"text":" economic aggregates: total output, unemployment, inflation, aggregate demand, the national or regional economy."}]},{"text":[{"text":"Central problem of economics:","bold":true},{"text":" scarcity, which forces choice."}]},{"text":[{"text":"4 factors of production:","bold":true},{"text":" land, labour, capital, entrepreneurship. Rewards: rent, wages, interest, profit."}]},{"text":[{"text":"Marginal rule:","bold":true},{"text":" if marginal benefit (MB) > marginal cost (MC), do "},{"text":"more","bold":true},{"text":" of the activity; if MB < MC, do less; stop where MB = MC."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Aggregate demand is a macro idea, so microeconomics is "},{"text":"not","bold":true},{"text":" concerned with it. An industry is still micro."}]},{"text":[{"text":"Exam options swap the two columns. Interest rates and foreign exchange are macro; opportunity cost and market competition are micro. Distribution of income is macro; distribution in the sense of a firm's distribution of goods is not on the list."}]},{"text":[{"text":"Money is not a factor of production.","bold":true},{"text":" A bank loan is finance used to buy capital; capital itself means man-made goods used in production (machines, buildings). The management phrase \"3Ms\" (men, money, materials) is a resource grouping, not the economist's list of factors."}]},{"text":[{"text":"Marginal thinking: if one more hour of overtime at a Shoprite branch brings ₦9,000 of extra sales margin but costs ₦6,000 in wages, MB > MC, so the hour is worth adding."}]}]}]},{"number":"1.3","title":"Goals of managerial economics and the decisions it guides","mustKnow":[{"type":"paragraph","text":[{"text":"Goals and objectives of ME (8):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Optimum resource allocation."}]},{"text":[{"text":"Achieving operational efficiency in business administration."}]},{"text":[{"text":"Enhancement and improved decision making in business."}]},{"text":[{"text":"Effective decisions on the use and distribution of resources (the 3Ms or the four factors of production)."}]},{"text":[{"text":"Decisions on "},{"text":"production techniques","bold":true},{"text":" and the balance between labour and technology, to achieve efficiency or profitability."}]},{"text":[{"text":"Decisions on "},{"text":"equipment replacement","bold":true},{"text":"."}]},{"text":[{"text":"Decisions on the "},{"text":"use of capital","bold":true},{"text":": loans, overdrafts, equity, debentures, bonds, donations (depending on the type of organisation)."}]},{"text":[{"text":"Decisions on "},{"text":"labour usage and size","bold":true},{"text":": number, category, employment, downsizing."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Optimum resource allocation:","bold":true},{"text":" resources are put to the uses that give the greatest benefit at the lowest cost (not kept idle, not spent fast, not shared equally)."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Match the case to the decision type:"}]},{"type":"table","header":[[{"text":"Case"}],[{"text":"Decision type"}]],"rows":[[[{"text":"Firm chooses bank loan, new equity or debentures for expansion"}],[{"text":"Use of capital"}]],[[{"text":"Non-profit school finances a hostel by donations or overdraft"}],[{"text":"Use of capital"}]],[[{"text":"Hospital replaces old X-ray machines now or in two years"}],[{"text":"Equipment replacement"}]],[[{"text":"Lagos bank cuts 150 staff and hires IT specialists"}],[{"text":"Labour usage and size"}]],[[{"text":"Aba garment factory decides number of sewing machines and tailors for lowest cost"}],[{"text":"Production technique (labour vs technology)"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Not","bold":true},{"text":" goals: employing as many workers as possible, removing every risk, replacing managers with government directives, preparing a statutory audit."}]}]}]},{"number":"1.4","title":"The three business categories","mustKnow":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Profit-making organisations:","bold":true},{"text":" sole proprietorship, partnership, limited liability companies, multinational companies (MNCs), and industry groups: FMCG, financial sector, oil and gas, construction, real estate."}]},{"text":[{"text":"Non-profit-making organisations:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"NGOs: Doctors Without Borders (MSF), Girls' Brigade, Red Cross Society."}]},{"text":[{"text":"Orphanages: SOS Children's Village, Little Saints, Living Fountain."}]},{"text":[{"text":"International and local clubs/societies: Rotary Club, Lions Club, Eko Tennis Club, Ikeja Golf Club."}]},{"text":[{"text":"Traditional societies and age grades."}]},{"text":[{"text":"Faith-based o$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua125', 3, $study_guide$rganisations: churches (RCCG, MFM, Methodist), Islamic societies (NASFAT), ATR (African Traditional Religion), fraternities."}]}]}]},{"text":[{"text":"Public sector:","bold":true},{"text":" State Government and its agencies, Local Government, Federal Government MDAs (ministries, departments, agencies), public corporations, welfare boards."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Foreign exchange markets are "},{"text":"not","bold":true},{"text":" one of the three categories."}]},{"text":[{"text":"A Red Cross branch in Ibadan splitting donations between first-aid training and flood relief is a "},{"text":"non-profit","bold":true},{"text":" applying ME. A State Commissioner for Health using population and cost data to site three health centres is the "},{"text":"public sector","bold":true},{"text":"."}]},{"text":[{"text":"Traps: a Federal Ministry is public sector, not a non-profit; a church is non-profit, not profit-making; a real-estate limited company is profit-making."}]}]}]},{"number":"1.5","title":"Objectives of managerial decisions","mustKnow":[{"type":"paragraph","text":[{"text":"Profit-seeking firms","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Profit maximisation:","bold":true},{"text":" choose output and price to make the gap TR − TC as large as possible. Standard theory assumes owners aim to maximise profit. Profit = TR − TC. At the best output MR = MC."}]},{"text":[{"text":"Wealth (value) maximisation:","bold":true},{"text":" maximise the present value of expected future profits."}],"blocks":[{"type":"paragraph","text":[{"text":"Value of the firm = sum over t = 1 to n of [profit in year t / (1 + i)^t], where i = discount rate."}]},{"type":"paragraph","text":[{"text":"It is better than simple profit maximisation because it accounts for the "},{"text":"timing and riskiness","bold":true},{"text":" of profits over many years (time value of money)."}]}]},{"text":[{"text":"Sales (revenue) maximisation (William Baumol):","bold":true},{"text":" maximise total revenue subject to a minimum acceptable profit."}]},{"text":[{"text":"Satisficing (Herbert Simon):","bold":true},{"text":" aim for a satisfactory level of profit, not the maximum, because managers have limited information and cannot evaluate every alternative (bounded rationality)."}]},{"text":[{"text":"Growth maximisation (Robin Marris):","bold":true},{"text":" maximise the growth rate of the firm (size, assets, market share)."}]},{"text":[{"text":"Principal-agent problem:","bold":true},{"text":" managers (agents) pursue their own interests, such as large offices or high salaries, instead of maximising value for the owners (principals)."}]}]},{"type":"paragraph","text":[{"text":"Non-profit organisations:","bold":true},{"text":" provide as much quality service as possible while covering costs (e.g. a church-owned mission hospital)."}]},{"type":"paragraph","text":[{"text":"Public sector:","bold":true},{"text":" maximise "},{"text":"net social benefit (social welfare)","bold":true},{"text":". Tool: "},{"text":"cost-benefit analysis","bold":true},{"text":", comparing total benefits to society with total costs to society."}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example 1 (profit vs sales maximisation). A Lagos snack maker, daily figures:"}]},{"type":"table","header":[[{"text":"Q"}],[{"text":"TR (₦)"}],[{"text":"TC (₦)"}],[{"text":"Profit (₦)"}]],"rows":[[[{"text":"10"}],[{"text":"100,000"}],[{"text":"70,000"}],[{"text":"30,000"}]],[[{"text":"20"}],[{"text":"180,000"}],[{"text":"110,000"}],[{"text":"70,000"}]],[[{"text":"30"}],[{"text":"240,000"}],[{"text":"150,000"}],[{"text":"90,000"}]],[[{"text":"40"}],[{"text":"280,000"}],[{"text":"200,000"}],[{"text":"80,000"}]],[[{"text":"50"}],[{"text":"300,000"}],[{"text":"270,000"}],[{"text":"30,000"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Profit maximiser: highest profit is ₦90,000, so produce "},{"text":"30 units","bold":true},{"text":"."}]},{"text":[{"text":"Baumol sales maximiser with minimum profit ₦75,000: outputs that meet the constraint are 30 (₦90,000) and 40 (₦80,000). Of these, TR is highest at 40 (₦280,000), so produce "},{"text":"40 units","bold":true},{"text":". Q = 50 has higher TR but profit of only ₦30,000 fails the constraint."}]},{"text":[{"text":"Lesson: a sales maximiser produces more than a profit maximiser."}]}]},{"type":"paragraph","text":[{"text":"Worked example 2 (value). Profits ₦10m at end of year 1 and ₦12m at end of year 2, i = 10%."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Year 1: 10 / 1.10 = ₦9.0909m."}]},{"text":[{"text":"Year 2: 12 / 1.10^2 = 12 / 1.21 = ₦9.9174m."}]},{"text":[{"text":"Value = 9.0909 + 9.9174 = "},{"text":"₦19.01m","bold":true},{"text":" (2 d.p.). Not ₦22m: money received later is worth less today."}]}]},{"type":"paragraph","text":[{"text":"Worked example 3 (choosing a project). X gives ₦15m at end of year 1; Y gives ₦16.2m at end of year 2; i = 10%."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"PV(X) = 15 / 1.10 = ₦13.64m. PV(Y) = 16.2 / 1.21 = ₦13.39m (2 d.p.)."}]},{"text":[{"text":"Choose "},{"text":"X","bold":true},{"text":". Picking Y because ₦16.2m > ₦15m ignores timing."}]}]},{"type":"paragraph","text":[{"text":"Worked example 4 (price choice). Kaduna cosmetics firm: low price TR ₦4.5m, TC ₦3.1m, profit ₦1.4m; medium TR ₦6.0m, TC ₦4.4m, profit ₦1.6m; high TR ₦7.2m, TC ₦5.9m, profit ₦1.3m. Choose the "},{"text":"medium","bold":true},{"text":" price. Neither lowest cost nor highest revenue decides it; profit does."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Satisficing case:","bold":true},{"text":" an Ibadan bakery owner earning ₦200,000 a month says it is good enough and stops searching for cheaper suppliers. "},{"text":"Sales maximisation case:","bold":true},{"text":" a detergent MD says \"push revenue as high as we can, provided profit does not fall below ₦50 million.\"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua125', 4, $study_guide$"}]},{"text":[{"text":"Do not swap the names: "},{"text":"Simon = satisficing","bold":true},{"text":", "},{"text":"Baumol = sales maximisation","bold":true},{"text":"."}]}]}]},{"number":"1.6","title":"Steps in managerial decision making","mustKnow":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Define the problem","bold":true},{"text":" (always first)."}]},{"text":[{"text":"Determine the objective","bold":true},{"text":" (e.g. maximise profit or social welfare)."}]},{"text":[{"text":"Identify (explore) the alternatives.","bold":true}]},{"text":[{"text":"Evaluate the alternatives:","bold":true},{"text":" predict the likely costs, benefits and consequences of each."}]},{"text":[{"text":"Choose the best alternative and implement it.","bold":true}]},{"text":[{"text":"Perform sensitivity analysis and monitor the results.","bold":true}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Sensitivity analysis:","bold":true},{"text":" testing how the best decision would change if key assumptions (expected price, cost, demand) turned out different."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Core order to memorise: define the problem → identify alternatives → evaluate alternatives → choose and implement."}]},{"text":[{"text":"A Kano distributor's logistics manager has listed three ways to cut delivery delays. The next step is to "},{"text":"evaluate the costs and benefits of each","bold":true},{"text":", not to implement the first one on the list or restate the mission."}]},{"text":[{"text":"If a medium price for Indomie cartons is best only when flour costs stay below a certain level, sensitivity analysis shows the manager how far costs can rise before the choice changes."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"ME = economic theories, concepts and models used for business decisions in any organisation."}]},{"text":[{"text":"It is applied, normative, mainly micro but also macro, and links economics with the decision sciences."}]},{"text":[{"text":"Micro scope: demand and supply, production, equilibrium, opportunity cost, profit maximisation, market competition. Macro scope: population, foreign exchange, interest rates, output, unemployment, income distribution."}]},{"text":[{"text":"Three categories: profit-making, non-profit-making, public sector."}]},{"text":[{"text":"8 goals of ME, including decisions on production technique, equipment replacement, use of capital, labour usage and size."}]},{"text":[{"text":"Firm objectives: profit, wealth/value (PV), sales (Baumol), satisficing (Simon), growth (Marris). Non-profits: maximum service at cost. Public sector: net social benefit via cost-benefit analysis."}]},{"text":[{"text":"Do more of an activity while MB > MC."}]},{"text":[{"text":"Decision steps start with defining the problem and end with sensitivity analysis and monitoring."}]}]}],"theory":{"itemId":"e310cac9-bb61-5215-81d6-0a503d9c8621","question":[{"type":"paragraph","text":[{"text":"A firm expects profits of ₦8m, ₦9m and ₦10m at the end of years 1, 2 and 3. Using a 12% discount rate (compounded annually), find the value of the firm to 2 decimal places."}]}]},"practice":[{"topic":"Introduction to Managerial Economics and Managerial Decisions","named":false}]}},{"kind":"note","itemId":"4f7d8ed6-befd-5d55-bce3-e1174f8d5e61","sourceKey":"guide-topic:2","position":2,"payload":{"title":"Opportunity Cost in Business","body":"The meaning of opportunity cost and why it exists; how to calculate it (the RMPIC − RICP formula and the next-best-alternative rule); explicit, implicit, sunk, marginal and incremental costs; accounting vs economic profit; the production possibility frontier; opportunity cost in operations and capital structure; implications, limitations and the four decision factors.","noteType":"guide_topic","number":2,"mustKnow":[{"text":"The meaning of opportunity cost and why it exists; how to calculate it (the RMPIC − RICP formula and the next-best-alternative rule); explicit, implicit, sunk, marginal and incremental costs; accounting vs economic profit; the production possibility frontier; opportunity cost in operations and capital structure; implications, limitations and the four decision factors."}],"lessons":[{"number":"2.1","title":"Meaning of opportunity cost","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Opportunity cost:","bold":true},{"text":" the potential benefit that a business, investor or consumer misses out on when choosing one alternative over another. Put simply, the forgone benefit from the option not chosen."}]},{"text":[{"text":"Economist's measure:","bold":true},{"text":" the value of the "},{"text":"next best alternative","bold":true},{"text":" given up (not the total of every alternative, not the price of the item chosen)."}]},{"text":[{"text":"Second definition:","bold":true},{"text":" the cost of time, effort and/or energy used to make Choice A that can no longer be used to make Choice B."}]},{"text":[{"text":"It can include "},{"text":"money, time and effort","bold":true},{"text":". A choice can have an opportunity cost even when no money is paid."}]},{"text":[{"text":"\"There is no such thing as a free lunch\":","bold":true},{"text":" every choice has a cost because time and energy are given up even if no money changes hands."}]},{"text":[{"text":"Why it exists:","bold":true},{"text":" resources are "},{"text":"scarce","bold":true},{"text":" and have "},{"text":"alternative uses","bold":true},{"text":". Scarcity is the central problem of economics."}]},{"text":[{"text":"In business it is the "},{"text":"trade-off","bold":true},{"text":" you accept in exchange for the choice you make. It cannot be predicted with total certainty, but considering it leads to better decisions."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Tolu, a sales executive, can attend a product launch or a client meeting, both at 2 $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua125', 5, $study_guide$pm on Friday. She goes to the launch. Her opportunity cost is the "},{"text":"client meeting","bold":true},{"text":", not \"nothing\" because the launch was free."}]},{"text":[{"text":"A bakery spends its ₦3 million budget on a new oven; the next best use was a marketing campaign. Opportunity cost = "},{"text":"the marketing campaign","bold":true},{"text":", not the bread the oven makes or last year's repairs."}]},{"text":[{"text":"An office manager buys a sofa; the same money could have bought a water cooler and new wallpaper. Opportunity cost = "},{"text":"the water cooler and the wallpaper","bold":true},{"text":"."}]},{"text":[{"text":"More examples: a firm paying ₦1 billion interest on debt gives up upscaling, marketing or product development; a phone maker gives up making computers or keyboards; a holiday gives up a day's work; an employee who quits for a year of study gives up a year's wages."}]},{"text":[{"text":"Business choices: building a plant in Lagos instead of Accra, upgrading equipment instead of hiring workers, buying shares in MTN instead of GTBank."}]}]}]},{"number":"2.2","title":"Calculating opportunity cost","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Formula:","bold":true},{"text":" Opportunity cost = RMPIC − RICP"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"RMPIC = return on the most profitable investment choice."}]},{"text":[{"text":"RICP = return on the investment chosen to pursue."}]},{"text":[{"text":"It is simply the difference between the expected returns of the options. Works in ₦ or in %."}]}]}]},{"text":[{"text":"Percentage return","bold":true},{"text":" = return ÷ amount invested × 100."}]},{"text":[{"text":"Next-best rule:","bold":true},{"text":" when the question asks for the value of the next best alternative forgone (or when the best option was chosen), the opportunity cost is the return of the "},{"text":"best option not chosen","bold":true},{"text":"."}]},{"text":[{"text":"Compounding:","bold":true},{"text":" return in year n = principal × r × (1 + r)^(n − 1)."}]},{"text":[{"text":"Production trade-off:","bold":true},{"text":" opportunity cost of 1 unit of X = units of Y given up ÷ units of X gained."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Read the question for the method it names."}]},{"type":"paragraph","text":[{"text":"Worked example 1 (formula in ₦). Spare ₦5,000,000: treasury bills return ₦600,000; new equipment adds ₦450,000. Firm picks equipment."}]},{"type":"paragraph","text":[{"text":"Opportunity cost = 600,000 − 450,000 = "},{"text":"₦150,000","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Likewise: Market A ₦50m, Market B ₦35m, firm picks B: 50 − 35 = "},{"text":"₦15m","bold":true},{"text":" (not zero, not ₦85m). Port Harcourt firm: treasury bills ₦1,200,000 vs workshop ₦900,000, picks workshop: "},{"text":"₦300,000","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Worked example 2 (formula in %). Stock market 10% vs equipment 8%, firm picks equipment: 10% − 8% = "},{"text":"2%","bold":true},{"text":". Treasury bills 14% vs upgrade 9%: "},{"text":"5%","bold":true},{"text":". Three options P 12%, Q 15%, R 9%, firm picks R: RMPIC is the "},{"text":"highest","bold":true},{"text":" (15%), so 15% − 9% = "},{"text":"6%","bold":true},{"text":" (not 12% − 9%)."}]},{"type":"paragraph","text":[{"text":"Worked example 3 (convert to %). ₦4,000,000 in X returns ₦520,000; in Y returns ₦360,000; firm picks Y."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"X: 520,000 ÷ 4,000,000 × 100 = 13%. Y: 360,000 ÷ 4,000,000 × 100 = 9%."}]},{"text":[{"text":"Opportunity cost = 13% − 9% = "},{"text":"4%","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Worked example 4 (next best forgone). An Oyo farmer's plot: maize ₦450,000, cassava ₦380,000, yam ₦520,000. He plants yam (the best). Opportunity cost = next best = "},{"text":"maize, ₦450,000","bold":true},{"text":". Similarly, three projects each costing ₦3,000,000 return A ₦3,540,000, B ₦3,480,000, C ₦3,600,000. Net gains: A ₦540,000, B ₦480,000, C ₦600,000. Choosing C, opportunity cost = next best net gain = "},{"text":"₦540,000","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Worked example 5 (multi-year). ₦20 million: securities at 10% compounded give ₦2.0m, ₦2.2m, ₦2.42m in years 1-3 (total ₦6.62m). A machine adds ₦0.5m, ₦2.0m, ₦5.0m (total ₦7.5m). Securities win in years 1 and 2, but over three years the machine is better by 7.5 − 6.62 = "},{"text":"₦0.88m","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Worked example 6 (compounding and cumulative). ₦5,000,000 in securities at 12% compounded:"}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Year 1: 5,000,000 × 0.12 = ₦600,000."}]},{"text":[{"text":"Year 2: 600,000 × 1.12 = ₦672,000."}]},{"text":[{"text":"Year 3: 672,000 × 1.12 = "},{"text":"₦752,640","bold":true},{"text":" (= 5,000,000 × 0.12 × 1.12^2). Total ₦2,024,640."}]},{"text":[{"text":"A machine adds ₦300,000, ₦800,000, ₦1,200,000 (total ₦2,300,000). Machine better by 2,300,000 − 2,024,640 = "},{"text":"₦275,360","bold":true},{"text":"."}]},{"text":[{"text":"Cumulative: year 1 ₦300,000 vs ₦600,000; year 2 ₦1,100,000 vs ₦1,272,000; year 3 ₦2,300,000 vs ₦2,024,640. The machine first leads in "},{"text":"year 3","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Worked example 7 (other cases)."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Interest of ₦45,000,000 could instead fund marketing returning 18%: return given up = 45,000,000 × 0.18 = "},{"text":"₦8,100,000","bold":true},{"text":"."}]},{"text":[{"text":"A workshop makes 200 chairs or 50 tables: 1 table costs 200 ÷ 50 = "},{"text":"4 chairs","bold":true},{"text":" (1 chair costs 0.25 tables)."}]},{"text":[{"text":"A consultant earns ₦25,000 an hour. Queuing 3 hours costs her 3 × 25,000 = ₦75,000 in lost work; an agent charges ₦5,000. Pa$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua125', 6, $study_guide$ying the agent leaves her 75,000 − 5,000 = "},{"text":"₦70,000","bold":true},{"text":" better off."}]}]}]},{"number":"2.3","title":"Opportunity cost and other costs; accounting vs economic profit","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Explicit cost:","bold":true},{"text":" out-of-pocket payment (rent, salaries, raw materials, electricity bills) paid with the firm's assets and recorded in its financial statements."}]},{"text":[{"text":"Implicit cost:","bold":true},{"text":" no cash exchange; cannot be measured accurately for accounting; it "},{"text":"is","bold":true},{"text":" an opportunity cost, also called an "},{"text":"imputed cost","bold":true},{"text":". Examples: rent the owner could earn on her own building, interest forgone on her own savings, salary she gave up."}]},{"text":[{"text":"Sunk cost:","bold":true},{"text":" money already spent in the past that cannot be recovered whatever you decide (machinery, stock, a feasibility study). It is "},{"text":"irrelevant","bold":true},{"text":" to future decisions."}]},{"text":[{"text":"Sunk vs opportunity cost:","bold":true},{"text":" sunk cost is past spending; opportunity cost is the future return not earned because money was used elsewhere."}]},{"text":[{"text":"Marginal cost:","bold":true},{"text":" cost of producing "},{"text":"one extra unit","bold":true},{"text":". MC = change in TC."}]},{"text":[{"text":"Incremental cost:","bold":true},{"text":" cost of raising production by "},{"text":"more than one unit","bold":true},{"text":" at a time."}]}]},{"type":"table","header":[[{"text":"Profit"}],[{"text":"Formula"}]],"rows":[[[{"text":"Accounting profit"}],[{"text":"Revenue − explicit costs"}]],[[{"text":"Economic profit"}],[{"text":"Revenue − explicit costs − implicit costs"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Economic profit = 0 means "},{"text":"normal profit","bold":true},{"text":" (all resources earn what they could earn elsewhere). Positive = above-normal; negative = economic loss."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A Yaba printing shop's explicit cost is the rent paid to the landlord; rent she could collect by leasing her own building is implicit."}]},{"text":[{"text":"A juice company in Ogun spent ₦2.5m last year on a feasibility study: "},{"text":"sunk","bold":true},{"text":". When replacing an old machine, its "},{"text":"book value","bold":true},{"text":" is sunk and irrelevant; only future costs and benefits count."}]},{"text":[{"text":"Marginal: TC ₦500,000 at 100 crates, ₦503,200 at 101: MC = "},{"text":"₦3,200","bold":true},{"text":". Incremental: 100 to 150 crates, TC ₦500,000 to ₦640,000: incremental cost = "},{"text":"₦140,000","bold":true},{"text":" (₦2,800 per extra crate on average)."}]},{"text":[{"text":"Implicit rent: shop rentable at ₦150,000 a month: 150,000 × 12 = "},{"text":"₦1,800,000","bold":true},{"text":" a year. Savings of ₦8,000,000 at 11%: 8,000,000 × 0.11 = "},{"text":"₦880,000","bold":true},{"text":" a year."}]}]},{"type":"paragraph","text":[{"text":"Worked example (Lekki boutique). Revenue ₦12,000,000; explicit costs ₦7,500,000; forgone salary ₦2,400,000; own savings ₦5,000,000 that could earn 10%."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Accounting profit = 12,000,000 − 7,500,000 = ₦4,500,000."}]},{"text":[{"text":"Implicit costs = 2,400,000 + (5,000,000 × 0.10 = 500,000) = "},{"text":"₦2,900,000","bold":true},{"text":"."}]},{"text":[{"text":"Economic profit = 4,500,000 − 2,900,000 = "},{"text":"₦1,600,000","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Worked example (Emeka). Revenue ₦6,000,000; explicit ₦4,200,000; forgone job ₦2,100,000."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Accounting profit = "},{"text":"₦1,800,000","bold":true},{"text":"; economic profit = 1,800,000 − 2,100,000 = "},{"text":"−₦300,000","bold":true},{"text":"."}]},{"text":[{"text":"Meaning: he would earn ₦300,000 more a year by taking the paid job. It is not a cash loss in his accounts."}]},{"text":[{"text":"Revenue ₦9m, explicit ₦6m, implicit ₦3m: economic profit = "},{"text":"zero","bold":true},{"text":", a normal profit."}]},{"text":[{"text":"Bisi leaves a ₦1,800,000 job to study; tuition and books ₦600,000; living costs ₦900,000 are the same either way, so they are excluded. Economic cost = 600,000 + 1,800,000 = "},{"text":"₦2,400,000","bold":true},{"text":"."}]}]}]},{"number":"2.4","title":"Opportunity cost in operations and the PPF","mustKnow":[{"type":"paragraph","text":[{"text":"Operations where opportunity cost guides decisions:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Production:","bold":true},{"text":" making one product means not making another (phones vs computers)."}]},{"text":[{"text":"Investment:","bold":true},{"text":" securities vs new machinery, stock A vs stock B, new plant here vs there."}]},{"text":[{"text":"Pricing:","bold":true},{"text":" inputs should be valued at what they could earn elsewhere (current value), not their historical cost."}]},{"text":[{"text":"Resource allocation:","bold":true},{"text":" put scarce funds, staff and machine time where they earn the most."}]},{"text":[{"text":"Make-or-buy:","bold":true},{"text":" compare the cost of buying with the full cost of making, including what the capacity could earn on other work."}]},{"text":[{"text":"Capital structure:","bold":true},{"text":" the combination of debt and equity used to fund operations and growth; expressed as a debt-to-equity or debt-to-capital ratio. It affects value, risk and return."}]}]},{"type":"paragraph","text":[{"text":"Production possibility frontier (PPF/PPC):","bold":true},{"text":" shows the maximum combinations of two goods an economy or firm can produce with given resources and technology."}]},{"type":"table","header":[[{"text":"Point"}],[{"text":"Meaning"}]],"rows":[[[{"text":"On the curve"}],[{"text":"F$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua125', 7, $study_guide$ull, efficient use of resources"}]],[[{"text":"Inside the curve"}],[{"text":"Less than full employment (idle or wasted resources)"}]],[[{"text":"Outside the curve"}],[{"text":"Unattainable with current resources"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Moving along the curve, more of one good means less of the other: the slope shows opportunity cost. A curve bowed outward shows "},{"text":"increasing","bold":true},{"text":" opportunity cost. An outward shift means growth (more resources or better technology)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Debt and equity:","bold":true},{"text":" each carries an explicit cost (interest to lenders, dividends to shareholders) and an opportunity cost. For debt, money used to repay debt cannot be invested elsewhere. It asks whether the expansion debt makes possible earns more than outside investments. Firms weigh borrowing against issuing shares to find the balance that minimises opportunity costs. This is hard in practice because opportunity cost is "},{"text":"forward-looking","bold":true},{"text":": the actual rate of return on each option is unknown when the choice is made."}]},{"text":[{"text":"Pricing example:","bold":true},{"text":" a Balogun market trader bought fabric at ₦4,000 a yard; its replacement price is now ₦5,500. Pricing on ₦4,000 ignores the ₦5,500 she could get by reselling it."}]},{"text":[{"text":"Make-or-buy example:","bold":true},{"text":" making a part costs ₦800 per unit; buying costs ₦950. If the same machine time could make another product earning ₦250 per unit, the true cost of making = 800 + 250 = ₦1,050 > ₦950, so "},{"text":"buy","bold":true},{"text":"."}]}]}]},{"number":"2.5","title":"Implications, limitations and decision factors","mustKnow":[{"type":"paragraph","text":[{"text":"Implications for business operations:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Better decision-making:","bold":true},{"text":" more informed choices that maximise potential profits and minimise missed opportunities."}]},{"text":[{"text":"Resource allocation:","bold":true},{"text":" resources are used efficiently, in the most profitable way possible."}]}]},{"type":"paragraph","text":[{"text":"4 limitations of opportunity cost:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Subjective:","bold":true},{"text":" calculations rest on assumptions, not fact, so they are open to error or bias."}]},{"text":[{"text":"Difficult to quantify:","bold":true},{"text":" costs are not always financial; they are shaped by preferences, projections, strategy and ethos."}]},{"text":[{"text":"Hard to record:","bold":true},{"text":" projected outcomes mix financial and non-financial measures."}]},{"text":[{"text":"Cannot cover all factors:","bold":true},{"text":" changes in the economy, public policy and consumer confidence also drive outcomes."}]}]},{"type":"paragraph","text":[{"text":"4 other decision factors (besides opportunity cost):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Cost:","bold":true},{"text":" the expense of deciding and its consequences."}]},{"text":[{"text":"Time:","bold":true},{"text":" time is money; judge whether saving time or money matters more."}]},{"text":[{"text":"Utility:","bold":true},{"text":" value optimisation, the crux of decision-making."}]},{"text":[{"text":"Effort:","bold":true},{"text":" minimise the effort the chosen option requires."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"They are interdependent. "},{"text":"Guiding principle:","bold":true},{"text":" maximise utility and value created while minimising cost incurred, time spent and effort required."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A manager whose project returns rest on her own guesses about demand is warned the result may be biased: that is "},{"text":"subjectivity","bold":true},{"text":"."}]},{"text":[{"text":"Opportunity cost never produces a precise, certain figure, is not recorded exactly in the financial statements, and is used by all organisations, not only non-profits."}]},{"text":[{"text":"\"Popularity\" is "},{"text":"not","bold":true},{"text":" one of the four factors."}]},{"text":[{"text":"Marginal thinking ties in: a student studies one more hour when its marginal benefit exceeds its "},{"text":"marginal","bold":true},{"text":" cost (the next best use of that hour)."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Opportunity cost = benefit of the next best alternative given up; it exists because resources are scarce with alternative uses."}]},{"text":[{"text":"It covers money, time and effort; no free lunch."}]},{"text":[{"text":"Formula: RMPIC − RICP. If the best option was chosen, or the question asks for the next best forgone, use the next best option's return."}]},{"text":[{"text":"Explicit = cash and recorded; implicit = imputed, no cash; sunk = past and irrelevant; marginal = one more unit; incremental = more than one unit."}]},{"text":[{"text":"Accounting profit = revenue − explicit costs; economic profit also subtracts implicit costs. Zero economic profit = normal profit."}]},{"text":[{"text":"PPF: on = efficient, inside = unemployment, outside = unattainable."}]},{"text":[{"text":"Capital structure = debt and equity mix; debt carries an opportunity cost."}]},{"text":[{"text":"4 limitations: subjective, hard to quantify, hard to record, cannot cover all factors. 4 factors: cost, time, utility, effort."}]}]}],"theory":{"itemId":"05c9ca48-cb8f-5ac6-a10d-bd84f49d7fe2","question":[{"type":"paragraph","text":[{"text":"Funke earns revenue of ₦10,000,000 from her catering firm. Explicit costs are ₦6,500,000. She gave up a salary of ₦1,500,000 and put in ₦4,000,000 of her own savings that could earn 12% a year. Find her accounting profit and economic profit."}]}]},"practice":[{"topic":"Oppor$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua125', 8, $study_guide$tunity Cost in Business","named":false}]}},{"kind":"note","itemId":"fedf8961-0e2d-5399-82eb-772010533853","sourceKey":"guide-topic:3","position":3,"payload":{"title":"Market Attractiveness, Demand Analysis and the Product Life Cycle","body":"What a market and market attractiveness are; the factors and frameworks (Porter, PESTEL, SWOT, BCG) and the weighted-score method; demand, the law of demand, its determinants and exceptions; shifts versus movements and equilibrium; price, income and cross elasticity with computations; demand estimation; the four stages of the product life cycle and the strategy for each.","noteType":"guide_topic","number":3,"mustKnow":[{"text":"What a market and market attractiveness are; the factors and frameworks (Porter, PESTEL, SWOT, BCG) and the weighted-score method; demand, the law of demand, its determinants and exceptions; shifts versus movements and equilibrium; price, income and cross elasticity with computations; demand estimation; the four stages of the product life cycle and the strategy for each."}],"lessons":[{"number":"3.1","title":"Markets and market attractiveness","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Market (3 definitions):","bold":true},{"text":" (1) a place where official exchange of goods and services is done using a legal tender or medium of exchange; (2) a place where the factors of production are traded on agreed terms; (3) an intended destination for the sale of a product or service that fulfils the firm's economic objectives and satisfies the needs of society."}]},{"text":[{"text":"Market attractiveness:","bold":true},{"text":" the potential of a market to generate profits for a firm; the potential of a market to provide "},{"text":"long-term profitability and growth opportunities","bold":true},{"text":". It measures how good a market is for a business: how much money a firm can make selling there. A market that can give a lot of profit is attractive."}]}]},{"type":"paragraph","text":[{"text":"5 reasons it matters to managers:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Helps firms make "},{"text":"informed decisions about entering or investing","bold":true},{"text":" in a market (the main reason)."}]},{"text":[{"text":"Influences efficient "},{"text":"resource allocation","bold":true},{"text":"."}]},{"text":[{"text":"Useful for "},{"text":"strategic planning","bold":true},{"text":"."}]},{"text":[{"text":"Foundation for "},{"text":"competitive advantage","bold":true},{"text":" and sustainable growth."}]},{"text":[{"text":"Useful for effective "},{"text":"risk management","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"It does "},{"text":"not","bold":true},{"text":" guarantee profit in any market."}]},{"type":"paragraph","text":[{"text":"7 key factors:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Market size and growth potential:","bold":true},{"text":" large and growing beats small and stagnant. Market size = total revenue or number of customers; growth rate = percentage change in market size over time."}]},{"text":[{"text":"Competitive landscape and market structure:","bold":true},{"text":" lower competition = more attractive. Shaped by number of competitors, market share distribution, barriers to entry and exit, market concentration, price wars and differentiation strategies."}]},{"text":[{"text":"Customer needs and preferences:","bold":true},{"text":" strong needs = more attractive. Assess demographics and psychographics, needs and wants, loyalty and retention, purchasing power."}]},{"text":[{"text":"Barriers to entry and exit:","bold":true},{"text":" high barriers make a market "},{"text":"less","bold":true},{"text":" attractive to a new entrant. Determinants: economies of scale, capital requirements, regulatory barriers."}]},{"text":[{"text":"Profitability and revenue potential:","bold":true},{"text":" higher profitability = more appealing. Determinants: cost structures and pricing power, consumption trends, purchasing power, competitive intensity, entry barriers, economies of scale."}]},{"text":[{"text":"Regulatory environment:","bold":true},{"text":" favourable rules attract investment and innovation; unfavourable rules raise cost and risk. Covers tariffs, taxes and trade policies; environmental and labour regulations; registration requirements; ease of doing business; economic freedom."}]},{"text":[{"text":"Technological trends (innovation and disruption):","bold":true},{"text":" internet penetration, digital transformation, AI, automation, machine learning, low cost of technology development."}]}]},{"type":"paragraph","text":[{"text":"Other factors:","bold":true},{"text":" economic stability, risk factors, corporate governance, purchasing power parity (PPP)."}]},{"type":"paragraph","text":[{"text":"3 challenges in assessing attractiveness:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Data limitations:","bold":true},{"text":" accurate data may be hard to obtain."}]},{"text":[{"text":"Dynamic factors:","bold":true},{"text":" conditions and trends change rapidly."}]},{"text":[{"text":"Subjectivity:","bold":true},{"text":" different firms perceive attractiveness differently."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Tesla, MTN and Dangote Group assess attractiveness before entering new regions or sectors."}]},{"text":[{"text":"Nigerian application:","bold":true},{"text":" a population of over 220 million (market size); fintech growing at a CAGR of about 15% with Flutterwave and Paystack (growth); telecoms dominated by MTN, Airtel and Glo, so "},{"text":"low","bold":true},{"text":" attractiveness for a new entrant because of high competition and capital needs (competitive intensity); Dangote Cement's high margins (profit margins); tax incentives for agribusiness and renewable energy (regulation); internet penetration driving digital b$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua125', 9, $study_guide$anking and B2B, B2C, C2C and C2B payments (technological trends)."}]},{"text":[{"text":"Trap on barriers:","bold":true},{"text":" high barriers are bad news for a firm trying to "},{"text":"enter","bold":true},{"text":" (Kola Foods facing huge capital needs, scale economies and hard-to-get licences finds the market less attractive). For firms already "},{"text":"inside","bold":true},{"text":", high barriers protect profits; long-term profits of existing firms are most threatened when barriers are "},{"text":"low","bold":true},{"text":", because newcomers flood in."}]},{"text":[{"text":"An "},{"text":"emerging","bold":true},{"text":" market is more attractive than a saturated one mainly because of "},{"text":"higher growth potential","bold":true},{"text":" (not lower risk or better data)."}]},{"text":[{"text":"Things that are "},{"text":"not","bold":true},{"text":" attractiveness factors: the number of shareholders or the age of the chief executive of the firm doing the analysis. Customer psychographics belong to customer needs, "},{"text":"not","bold":true},{"text":" to the regulatory environment."}]}]}]},{"number":"3.2","title":"Attractiveness frameworks and the weighted-score method","mustKnow":[{"type":"paragraph","text":[{"text":"4 frameworks:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Porter's Five Forces:","bold":true},{"text":" analyses competitive forces in a market."}]},{"text":[{"text":"PESTEL:","bold":true},{"text":" Political, Economic, Social, Technological, Environmental, Legal factors."}]},{"text":[{"text":"SWOT:","bold":true},{"text":" Strengths and Weaknesses ("},{"text":"internal","bold":true},{"text":"), Opportunities and Threats ("},{"text":"external","bold":true},{"text":")."}]},{"text":[{"text":"BCG matrix:","bold":true},{"text":" market growth rate against relative market share."}]}]},{"type":"paragraph","text":[{"text":"Porter's five forces and what drives each:","bold":true}]},{"type":"table","header":[[{"text":"Force"}],[{"text":"Driven by"}]],"rows":[[[{"text":"Rivalry among existing competitors (the centre)"}],[{"text":"number and diversity of competitors, industry concentration, industry growth, quality differences, brand loyalty, exit barriers, switching costs"}]],[[{"text":"Threat of new entrants"}],[{"text":"barriers to entry, economies of scale, brand loyalty, capital requirements, cumulative experience, government policies, access to distribution channels, switching costs"}]],[[{"text":"Bargaining power of suppliers"}],[{"text":"number and size of suppliers, uniqueness of each supplier's product, the firm's ability to substitute"}]],[[{"text":"Bargaining power of buyers"}],[{"text":"number of customers, size of each order, differences between competitors, price sensitivity, ability to substitute, information available, switching costs"}]],[[{"text":"Threat of substitute products"}],[{"text":"number of substitutes, buyers' propensity to substitute, relative price-performance, perceived differentiation, switching costs"}]]]},{"type":"paragraph","text":[{"text":"Inflation, corporate governance, PPP and \"power of government regulators\" are "},{"text":"not","bold":true},{"text":" among the five forces."}]},{"type":"paragraph","text":[{"text":"BCG matrix:","bold":true}]},{"type":"table","header":[[],[{"text":"High relative share"}],[{"text":"Low relative share"}]],"rows":[[[{"text":"High growth"}],[{"text":"Star"}],[{"text":"Question mark"}]],[[{"text":"Low growth"}],[{"text":"Cash cow"}],[{"text":"Dog"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Relative market share (RMS) = own sales / sales of the largest competitor","bold":true},{"text":" (if you are not the leader, divide by the leader's sales). Above 1.0 means you lead."}]}]},{"type":"paragraph","text":[{"text":"Weighted-score method:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Weight","bold":true},{"text":" = how important the factor is to the business. Weights add to 100%, so a missing weight = 100% minus the others."}]},{"text":[{"text":"Score","bold":true},{"text":" = how favourable the market is on that factor, rated 1 to 10."}]},{"text":[{"text":"Weighted score = weight x score.","bold":true},{"text":" "},{"text":"Total","bold":true},{"text":" = sum of weighted scores = overall attractiveness."}]}]},{"type":"paragraph","text":[{"text":"Market measures:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Growth rate = (new size - old size) / old size x 100"}]},{"text":[{"text":"Market size (revenue) = number of customers x average spend per period"}]},{"text":[{"text":"Future value with CAGR = present value x (1 + g)^n"}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Five-forces cases:","bold":true},{"text":" a cinema in Abuja losing customers to cheap streaming = threat of substitutes. Bottled-water buyers ordering in bulk, comparing prices online and switching at no cost = strong buyer power. A cocoa processor in Ondo with only two suppliers of unique grades = strong supplier power. Inflation and interest rates in a PESTEL = "},{"text":"economic","bold":true},{"text":" factors. A well-funded foreign rival about to enter = a "},{"text":"threat","bold":true},{"text":" in SWOT."}]},{"text":[{"text":"Worked table","bold":true},{"text":" (scores out of 10):"}],"blocks":[{"type":"table","header":[[{"text":"Factor"}],[{"text":"Weight"}],[{"text":"Score"}],[{"text":"Weighted"}]],"rows":[[[{"text":"Market size"}],[{"text":"20%"}],[{"text":"8"}],[{"text":"1.60"}]],[[{"text":"Market growth rate"}],[{"text":"15%"}],[{"text":"9"}],[{"text":"1.35"}]],[[{"text":"Profit margins"}],[{"text":"15%"}],[{"text":"7"}],[{"text":"1.05"}]],[[{"text":"Competitive intensity"}],[{"text":"10%"}],[{"text":"5"}],[{"text":"0.50"}]],[[{"text":"Customer needs"}],[{"text":"10%"}],[{"text":"8"}],[{"text":"0.80"}]],[[{"text":"Barriers to entry"}],[{"text":"10%"}],[{"text":"6"}],[{"text":"0.60$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua125', 10, $study_guide$"}]],[[{"text":"Technological trends"}],[{"text":"10%"}],[{"text":"7"}],[{"text":"0.70"}]],[[{"text":"Regulatory environment"}],[{"text":"5%"}],[{"text":"4"}],[{"text":"0.20"}]],[[{"text":"Economic stability"}],[{"text":"5%"}],[{"text":"9"}],[{"text":"0.45"}]],[[{"text":"Risk factors"}],[{"text":"5%"}],[{"text":"5"}],[{"text":"0.25"}]],[[{"text":"Total"}],[{"text":"100%"}],[],[{"text":"7.50"}]]]},{"type":"paragraph","text":[{"text":"A total of 7.5 is "},{"text":"moderately attractive","bold":true},{"text":": strong on size, growth and stability; weak on competition and regulation. Repeat for several markets and pick the highest total; never just average the scores."}]}]},{"text":[{"text":"Comparing markets:","bold":true},{"text":" profitability 60%, competition 40%. Market A scores 9 and 3: 0.6 x 9 + 0.4 x 3 = 5.4 + 1.2 = 6.6. Market B scores 6 and 8: 3.6 + 3.2 = 6.8. "},{"text":"B wins","bold":true},{"text":" even though A has the higher profit score."}]},{"text":[{"text":"Revised score:","bold":true},{"text":" a factor weighted 20% moves from 6 to 9. The total changes by 0.20 x (9 - 6) = "},{"text":"+0.60","bold":true},{"text":"."}]},{"text":[{"text":"Required score:","bold":true},{"text":" threshold 7.5; factors weighing 80% already give 5.9. Remaining weight 20%: needed score = (7.5 - 5.9) / 0.20 = "},{"text":"8","bold":true},{"text":"."}]},{"text":[{"text":"Growth rate:","bold":true},{"text":" a market grows from ₦50 billion to ₦60 billion: (60 - 50) / 50 = "},{"text":"20%","bold":true},{"text":". Trap: dividing by the new figure gives 16.67%."}]},{"text":[{"text":"Market size:","bold":true},{"text":" 1.5 million subscribers x ₦2,000 a month x 12 = "},{"text":"₦36 billion a year","bold":true},{"text":". Trap: forgetting the x 12."}]},{"text":[{"text":"CAGR:","bold":true},{"text":" ₦100 billion growing at 20% for 2 years = 100 x 1.2^2 = "},{"text":"₦144 billion","bold":true},{"text":", not ₦140 billion (growth compounds)."}]},{"text":[{"text":"BCG computation:","bold":true},{"text":" your sales ₦60 million, largest rival ₦40 million: RMS = 1.5 (high). Market growth 12% (above a 10% cut-off) = "},{"text":"star","bold":true},{"text":". Sales ₦10 million against a leader's ₦40 million: RMS = 0.25 (low); at 15% growth it is a "},{"text":"question mark","bold":true},{"text":", at 5% growth a "},{"text":"dog","bold":true},{"text":"."}]}]}]},{"number":"3.3","title":"Demand, the law of demand and its determinants","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Demand:","bold":true},{"text":" the quantity of a good consumers are "},{"text":"willing and able","bold":true},{"text":" to buy at various prices over a period. "},{"text":"Quantity demanded:","bold":true},{"text":" the specific amount buyers are willing and able to buy at "},{"text":"one particular price","bold":true},{"text":"."}]},{"text":[{"text":"Law of demand:","bold":true},{"text":" other things being equal (ceteris paribus), as price falls, "},{"text":"quantity demanded","bold":true},{"text":" rises; as price rises, quantity demanded falls. Price and quantity demanded are inversely related."}]},{"text":[{"text":"Demand curve:","bold":true},{"text":" slopes "},{"text":"downward from left to right","bold":true},{"text":". It is drawn holding constant "},{"text":"income, tastes and the prices of other goods","bold":true},{"text":" (the good's own price is on the axis, so it is not held constant)."}]},{"text":[{"text":"Demand function:","bold":true},{"text":" Qd = f(P, Y, Pr, T, E, N), where P = own price, Y = income, Pr = prices of related goods, T = tastes, E = expectations, N = number of buyers (population). Linear form: Qd = a - bP."}]}]},{"type":"paragraph","text":[{"text":"Why the curve slopes down (3 reasons):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Substitution effect:","bold":true},{"text":" at a higher price, people switch to (search for) substitutes."}]},{"text":[{"text":"Income effect:","bold":true},{"text":" a higher price cuts real income, so people buy less."}]},{"text":[{"text":"Diminishing marginal utility:","bold":true},{"text":" "},{"text":"marginal utility","bold":true},{"text":" is the extra satisfaction from one more unit; it falls as you consume more, so you buy more only at a lower price."}]}]},{"type":"paragraph","text":[{"text":"Determinants of demand:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Income:","bold":true},{"text":" normal good, demand rises with income; inferior good, demand falls as income rises."}]},{"text":[{"text":"Prices of related goods:","bold":true},{"text":" "},{"text":"substitutes","bold":true},{"text":" (price of one up, demand for the other up); "},{"text":"complements","bold":true},{"text":" (price of one up, demand for the other down)."}]},{"text":[{"text":"Tastes and preferences","bold":true},{"text":" (advertising, fashion)."}]},{"text":[{"text":"Expectations","bold":true},{"text":" of future prices and incomes."}]},{"text":[{"text":"Population and number of buyers.","bold":true}]}]},{"type":"paragraph","text":[{"text":"The "},{"text":"cost of producing","bold":true},{"text":" the good is a supply factor, "},{"text":"not","bold":true},{"text":" a determinant of demand."}]},{"type":"paragraph","text":[{"text":"Kinds of demand and goods:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Individual demand","bold":true},{"text":" (one consumer) vs "},{"text":"market demand","bold":true},{"text":" (sum of all consumers)."}]},{"text":[{"text":"Derived (induced) demand:","bold":true},{"text":" tied to demand for a parent product (tyres from cars). "},{"text":"Autonomous (direct) demand:","bold":true},{"text":" not tied to another product."}]},{"text":[{"text":"Consumer (final) goods:","bold":true},{"text":" bought by households for own use. "},{"text":"Producer (intermediate) goods:","bold":true},{"text":" used in further manufacturing, processing or resale $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua125', 11, $study_guide$(flour bought by a bakery)."}]}]},{"type":"paragraph","text":[{"text":"Exceptions to the law of demand:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Veblen (prestige) goods:","bold":true},{"text":" luxury watches, designer bags; bought more as price rises for status."}]},{"text":[{"text":"Giffen goods:","bold":true},{"text":" very inferior staples for poor households; a price rise cuts real income so much that they buy more of the staple."}]},{"text":[{"text":"Expectations of further price rises:","bold":true},{"text":" buyers stock up while price is rising (on a diagram, the expectation shifts demand right)."}]},{"text":[{"text":"Price-quality illusion (ignorance):","bold":true},{"text":" buyers judge quality by price."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" the law is about "},{"text":"quantity demanded","bold":true},{"text":"; \"as price falls, demand increases\" is wrong."}]},{"text":[{"text":"Coca-Cola and Pepsi are substitutes; cars and petrol, printers and ink, crackers and cheese are complements. Cheaper cheese means more cheese bought, more demand for crackers and a higher cracker price: "},{"text":"complements","bold":true},{"text":". If a fall in one good's price cuts demand for another, they are "},{"text":"substitutes","bold":true},{"text":"."}]},{"text":[{"text":"If coffee demand falls when income falls, coffee is a "},{"text":"normal","bold":true},{"text":" good. Second-hand clothing and cheap staples are often inferior for Nigerian households whose incomes rise."}]},{"text":[{"text":"Bread, a newspaper or a soft drink with many rivals obeys the law; a luxury designer watch is the classic exception."}]}]}]},{"number":"3.4","title":"Shifts, movements, equilibrium and demand estimation","mustKnow":[{"type":"table","header":[[{"text":"Change in quantity demanded"}],[{"text":"Change in demand"}]],"rows":[[[{"text":"caused only by the good's "},{"text":"own price","bold":true}],[{"text":"caused by income, related prices, tastes, expectations, population"}]],[[{"text":"movement along","bold":true},{"text":" the same curve"}],[{"text":"the "},{"text":"whole curve shifts","bold":true}]],[[{"text":"price rise = movement up/left; price fall = movement down/right"}],[{"text":"increase = shift "},{"text":"right","bold":true},{"text":"; decrease = shift "},{"text":"left","bold":true}]]]},{"type":"paragraph","text":[{"text":"For a normal good, demand shifts left when:","bold":true},{"text":" substitutes get cheaper, complements get dearer, or incomes fall. "},{"text":"It shifts right when:","bold":true},{"text":" income rises (normal good) or falls (inferior good), a substitute's price rises, a complement's price falls, or a price rise is expected."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Equilibrium:","bold":true},{"text":" quantity demanded = quantity supplied at the prevailing price."}]},{"text":[{"text":"Excess demand (shortage):","bold":true},{"text":" price "},{"text":"rises","bold":true},{"text":". "},{"text":"Excess supply (surplus):","bold":true},{"text":" price falls."}]},{"text":[{"text":"Price rationing:","bold":true},{"text":" in a free market, price increases distribute what is available to those willing and able to pay the most."}]}]},{"type":"paragraph","text":[{"text":"Effect of shifts:","bold":true}]},{"type":"table","header":[[{"text":"Change"}],[{"text":"Equilibrium price"}],[{"text":"Equilibrium quantity"}]],"rows":[[[{"text":"Demand up only"}],[{"text":"up"}],[{"text":"up"}]],[[{"text":"Demand down only"}],[{"text":"down"}],[{"text":"down"}]],[[{"text":"Demand up, supply up"}],[{"text":"indeterminate"}],[{"text":"up"}]],[[{"text":"Demand down, supply down"}],[{"text":"indeterminate"}],[{"text":"down"}]],[[{"text":"Demand up, supply down"}],[{"text":"up"}],[{"text":"indeterminate"}]],[[{"text":"Demand down, supply up"}],[{"text":"down"}],[{"text":"indeterminate"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Demand estimation (measurement) methods:","bold":true},{"text":" (1) consumer surveys and interviews; (2) market experiments (test markets, varying price in selected outlets); (3) statistical methods (trend projection, regression) that fit a demand function to past data."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A fall in the quantity of Pepsi bought is best explained by a rise in "},{"text":"Pepsi's own price","bold":true},{"text":" (a movement). A wine price rise from ₦15,000 to ₦20,000 a bottle cuts "},{"text":"quantity demanded","bold":true},{"text":", not demand."}]},{"text":[{"text":"A change in the price of compact discs does "},{"text":"not","bold":true},{"text":" shift the CD demand curve; changes in cassette prices, income or wealth do."}]},{"text":[{"text":"Ibadan incomes rise and people buy more chicken at every price: "},{"text":"rightward shift","bold":true},{"text":". Buyers expect rice to rise sharply next month: today's demand shifts "},{"text":"right","bold":true},{"text":"."}]},{"text":[{"text":"An increase in demand raises "},{"text":"quantity supplied","bold":true},{"text":" (a movement along supply). Price and quantity both rising signals an "},{"text":"increase in demand","bold":true},{"text":"."}]},{"text":[{"text":"Demand function in use:","bold":true},{"text":" soap demand Qd = 800 - 5P. At P = ₦60, Qd = 800 - 300 = "},{"text":"500 units","bold":true},{"text":". Such equations are estimated by regression on past sales, prices and incomes."}]}]}]},{"number":"3.5","title":"Elasticity of demand","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Price elasticity of demand (PED):","bold":true},{"text":" responsiveness of quantity demanded to a change in the good's "},{"text":"own price","bold":true},{"text":"."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"PED = % change in quantity demanded / % change in price (quoted$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua125', 12, $study_guide$ in absolute value; the sign is negative)."}]}]}]},{"text":[{"text":"Income elasticity (YED)","bold":true},{"text":" = % change in quantity demanded / % change in income."}]},{"text":[{"text":"Cross elasticity (XED)","bold":true},{"text":" = % change in quantity demanded of good X / % change in price of good Y. It covers both substitutes and complements."}]}]},{"type":"paragraph","text":[{"text":"Percentage-change methods:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Original basis: %change = (new - old) / old x 100."}]},{"text":[{"text":"Midpoint (arc): %change in Q = (Q2 - Q1) / [(Q1 + Q2)/2] x 100; same for P."}]},{"text":[{"text":"Point elasticity: PED = (dQ/dP) x (P/Q). For Qd = a - bP, dQ/dP = -b."}]}]},{"type":"paragraph","text":[{"text":"Interpreting values:","bold":true}]},{"type":"table","header":[[{"text":"Value"}],[{"text":"Name"}]],"rows":[[[{"text":"PED = 0"}],[{"text":"perfectly inelastic (quantity does not change)"}]],[[{"text":"PED below 1"}],[{"text":"inelastic"}]],[[{"text":"PED = 1"}],[{"text":"unitary elastic"}]],[[{"text":"PED above 1"}],[{"text":"elastic"}]],[[{"text":"PED infinite"}],[{"text":"perfectly elastic (tiny price change, infinite quantity change)"}]],[[{"text":"YED below 0"}],[{"text":"inferior good"}]],[[{"text":"YED 0 to 1"}],[{"text":"normal necessity"}]],[[{"text":"YED above 1"}],[{"text":"luxury"}]],[[{"text":"XED positive"}],[{"text":"substitutes"}]],[[{"text":"XED negative"}],[{"text":"complements"}]],[[{"text":"XED zero"}],[{"text":"unrelated"}]]]},{"type":"paragraph","text":[{"text":"Total revenue (TR = P x Q) rule:","bold":true}]},{"type":"table","header":[[{"text":"Demand"}],[{"text":"Price rise"}],[{"text":"Price cut"}]],"rows":[[[{"text":"Elastic"}],[{"text":"TR falls"}],[{"text":"TR rises"}]],[[{"text":"Inelastic"}],[{"text":"TR rises"}],[{"text":"TR falls"}]],[[{"text":"Unitary"}],[{"text":"TR unchanged"}],[{"text":"TR unchanged"}]]]},{"type":"paragraph","text":[{"text":"Determinants of PED (demand is more elastic when):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"More close "},{"text":"substitutes","bold":true},{"text":" exist (a single brand is more elastic than the whole product class)."}]},{"text":[{"text":"The good is a "},{"text":"luxury","bold":true},{"text":" rather than a necessity."}]},{"text":[{"text":"A "},{"text":"larger share of income","bold":true},{"text":" is spent on it."}]},{"text":[{"text":"More time","bold":true},{"text":" has passed since the price change (long run more elastic than short run), because over time "},{"text":"consumers are better able to find substitutes","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Basic:","bold":true},{"text":" price up 10%, quantity down 15%: PED = 1.5, "},{"text":"elastic","bold":true},{"text":". Price up 50%, quantity down 90%: 90/50 = "},{"text":"1.8, elastic","bold":true},{"text":". PED 0.75 = inelastic."}]},{"text":[{"text":"Original basis:","bold":true},{"text":" price ₦100 to ₦120 (+20%), quantity 500 to 450 (-10%). PED = 10/20 = "},{"text":"0.5, inelastic","bold":true},{"text":"."}]},{"text":[{"text":"Midpoint:","bold":true},{"text":" price ₦200 to ₦150, quantity 40 to 60. %ΔQ = 20 / 50 = 40%; %ΔP = -50 / 175 = -28.57%. PED = 40 / 28.57 = "},{"text":"1.4","bold":true},{"text":" (elastic; exactly 1.40, since 0.40 / (50/175) = 1.4). Also, quantity 1,000 to 1,500 when price falls ₦150 to ₦100: 500/1,250 = 40% and 50/125 = 40%, so PED = "},{"text":"1.0","bold":true},{"text":"."}]},{"text":[{"text":"TR check:","bold":true},{"text":" 100 units at ₦10,000 = ₦1,000,000; 75 units at ₦15,000 = ₦1,125,000. A price rise raised TR, so demand is "},{"text":"inelastic","bold":true},{"text":"."}]},{"text":[{"text":"Predicting quantity:","bold":true},{"text":" PED = -2, price up 5%: quantity falls 2 x 5 = 10%. Sales of 3,000 become "},{"text":"2,700","bold":true},{"text":". If PED = 0.5, a 10% price "},{"text":"cut","bold":true},{"text":" raises quantity by 5%; if PED = 5, a 10% rise cuts quantity by 50%."}]},{"text":[{"text":"Required price change:","bold":true},{"text":" PED = -2; to sell 12% more, cut price by 12 / 2 = "},{"text":"6%","bold":true},{"text":"."}]},{"text":[{"text":"Revenue effect:","bold":true},{"text":" 1,000 units at ₦500 (TR ₦500,000), PED = -0.5, price raised to ₦600 (+20%). Quantity falls 0.5 x 20 = 10% to 900. New TR = 900 x ₦600 = ₦540,000, a "},{"text":"rise of ₦40,000","bold":true},{"text":"."}]},{"text":[{"text":"YED:","bold":true},{"text":" income ₦80,000 to ₦100,000 (+25%), Indomie packs 10 to 11 (+10%): YED = 10/25 = "},{"text":"0.4, normal necessity","bold":true},{"text":". Income +20%, quantity -5%: YED = "},{"text":"-0.25, inferior","bold":true},{"text":". YED of 1.5 = luxury."}]},{"text":[{"text":"XED:","bold":true},{"text":" Coke rises ₦300 to ₦360 (+20%); Pepsi sales 1,000 to 1,100 (+10%): XED = "},{"text":"+0.5, substitutes","bold":true},{"text":". A console's price falls 10%, game sales rise 20%: XED = 20 / -10 = "},{"text":"-2.0, complements","bold":true},{"text":". A rise in good 1's price that cuts quantity of good 2 means XED is "},{"text":"negative","bold":true},{"text":"."}]},{"text":[{"text":"Point elasticity:","bold":true},{"text":" Qd = 1,000 - 4P. At P = ₦100, Q = 600; PED = -4 x 100/600 = "},{"text":"-0.67","bold":true},{"text":" (0.67 absolute, rounded). At P = ₦150, Q = 400; PED = -4 x 150/400 = -1.5. The "},{"text":"slope is constant","bold":true},{"text":" on a straight line but "},{"text":"elasticity changes","bold":true},{"text":" from point to point."}]},{"text":[{"text":"Applications:","bold":true},{"text":" cigarette tax raises most revenue when demand is "},{"text":"inelastic","bold":true},{"text":". A TV maker cutting price 10% on inelastic demand sees revenue "},{"text":"fall","bold":true},{"text":". If supply rises and price falls but quantity is unchanged, PED is "},{"text":"zero","bold":true},{"text":". $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua125', 13, $study_guide$Aglets (shoelace tips) take a tiny income share: "},{"text":"inelastic","bold":true},{"text":". Streaming gives cinema tickets more substitutes, so their PED "},{"text":"rises","bold":true},{"text":"."}]}]}]},{"number":"3.6","title":"The product life cycle (PLC)","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"PLC:","bold":true},{"text":" the course of a product's sales and profits over its life. "},{"text":"4 stages in order: introduction, growth, maturity, decline.","bold":true},{"text":" (Some add a "},{"text":"product development","bold":true},{"text":" stage before introduction, with zero sales and rising investment.)"}]}]},{"type":"table","header":[[{"text":"Feature"}],[{"text":"Introduction"}],[{"text":"Growth"}],[{"text":"Maturity"}],[{"text":"Decline"}]],"rows":[[[{"text":"Sales"}],[{"text":"low"}],[{"text":"rising rapidly"}],[{"text":"peak, levelling off"}],[{"text":"falling"}]],[[{"text":"Cost per customer"}],[{"text":"high"}],[{"text":"average"}],[{"text":"low"}],[{"text":"low"}]],[[{"text":"Profit"}],[{"text":"negative or little"}],[{"text":"rising"}],[{"text":"high, then falling"}],[{"text":"declining"}]],[[{"text":"Customers"}],[{"text":"innovators"}],[{"text":"early adopters"}],[{"text":"mass market"}],[{"text":"laggards"}]],[[{"text":"Competitors"}],[{"text":"few"}],[{"text":"growing number"}],[{"text":"stable, many, intense"}],[{"text":"declining number"}]],[[{"text":"Main aim"}],[{"text":"create awareness and trial"}],[{"text":"build market share"}],[{"text":"defend share, extend life"}],[{"text":"cut costs, harvest or drop"}]]]},{"type":"paragraph","text":[{"text":"Strategies:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Introduction:","bold":true},{"text":" heavy promotion to build awareness, limited distribution, basic product, price skimming or penetration."}]},{"text":[{"text":"Growth:","bold":true},{"text":" improve features, add new models, widen distribution, expand capacity, some price cuts to attract buyers."}]},{"text":[{"text":"Maturity:","bold":true},{"text":" extend life by "},{"text":"modifying the market","bold":true},{"text":" (new users, new uses), "},{"text":"modifying the product","bold":true},{"text":" (quality, features, style) or "},{"text":"modifying the marketing mix","bold":true},{"text":" (price, promotion, distribution)."}]},{"text":[{"text":"Decline:","bold":true},{"text":" "},{"text":"maintain","bold":true},{"text":", "},{"text":"harvest","bold":true},{"text":" (cut costs, ride remaining sales) or "},{"text":"drop","bold":true},{"text":" the product from the line."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A newly launched plant-based yoghurt with low sales, high promotion costs and little profit is in "},{"text":"introduction","bold":true},{"text":". A fintech payment app with fast-rising sales, improving profits and new rivals copying it is in "},{"text":"growth","bold":true},{"text":". A detergent brand whose sales have levelled at the peak, with most buyers already using such products and fierce price and promotion rivalry, is in "},{"text":"maturity","bold":true},{"text":"."}]},{"text":[{"text":"Traps:","bold":true},{"text":" withdrawing promotion, cutting outlets or sharp price rises are not maturity strategies; first-time awareness is introduction; new factories for soaring demand is growth."}]},{"text":[{"text":"Business implications:","bold":true},{"text":" the PLC guides budgeting (cash absorbed in introduction, generated in maturity), pricing, promotion and the timing of launches, so new products are growing as old ones decline."}]},{"text":[{"text":"A mature milk brand such as Peak launching small sachet sizes to reach low-income buyers is a maturity move (product and mix modification to win new users)."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Market attractiveness = potential for long-term profit and growth; 7 key factors plus economic stability, risk, governance, PPP; challenges: data, dynamics, subjectivity."}]},{"text":[{"text":"High entry barriers hurt entrants but protect incumbents; low barriers threaten incumbents' profits."}]},{"text":[{"text":"Porter's 5 forces (rivalry at the centre), PESTEL, SWOT (S and W internal), BCG (star, question mark, cash cow, dog; RMS = own sales / largest rival's)."}]},{"text":[{"text":"Weighted score = weight x score, summed; weight = importance, score = favourability."}]},{"text":[{"text":"Law of demand: price down, quantity demanded up, ceteris paribus; explained by substitution and income effects and diminishing marginal utility."}]},{"text":[{"text":"Own price = movement along the curve; any other determinant = shift."}]},{"text":[{"text":"PED above 1 elastic, below 1 inelastic; elastic: price cut raises TR. YED negative = inferior, 0 to 1 = necessity, above 1 = luxury. XED positive = substitutes, negative = complements."}]},{"text":[{"text":"Demand is more elastic with more substitutes, luxuries, bigger income share and more time."}]},{"text":[{"text":"PLC: introduction, growth, maturity, decline; extend maturity by modifying market, product or mix; in decline maintain, harvest or drop."}]}]}],"theory":{"itemId":"4bd3c121-03a7-5136-8083-ef24dea93d88","question":[{"type":"paragraph","text":[{"text":"A Surulere kiosk cuts the price of a chilled drink from ₦500 to ₦400, and daily sales rise from 200 to 300 bottles. Using the midpoint method, find the price elasticity of demand, classify it, and state what happened to total revenue."}]}]},"practice":[{"topic":"Market Attractiveness, Demand Analysis and Product Life Cycle","named":false}]}},{"kind":"note","itemId":"63b68675-b1e1-57d7-9126-21f695700242","sourceKey":"guide-topic:4","position":4,"payload":{"title":"Business Forecasting","body":"The meaning and importance of demand forecasting; the factors that affect it; its types (short, medium and long term; passive and active; internal; macro and micro; quali$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua125', 14, $study_guide$tative and quantitative; demand, sales, economic and technological); the techniques (surveys, statistical methods, econometric models, sales force composite, Delphi, barometric indicators, expert opinion, simulation); the steps; the challenges; and the forecast computations (moving averages, exponential smoothing, trend projection, growth, forecast error and MAD).","noteType":"guide_topic","number":4,"mustKnow":[{"text":"The meaning and importance of demand forecasting; the factors that affect it; its types (short, medium and long term; passive and active; internal; macro and micro; qualitative and quantitative; demand, sales, economic and technological); the techniques (surveys, statistical methods, econometric models, sales force composite, Delphi, barometric indicators, expert opinion, simulation); the steps; the challenges; and the forecast computations (moving averages, exponential smoothing, trend projection, growth, forecast error and MAD)."}],"lessons":[{"number":"4.1","title":"Meaning, significance and factors","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Demand forecasting:","bold":true},{"text":" a technique for anticipating future demand for a product, which tells a business the estimated quantity of a product or service that consumers may want to buy over a period of time."}]},{"text":[{"text":"Business forecasting","bold":true},{"text":" (wider): predicting future business conditions (demand, sales, costs, prices, the economy) so that managers can plan."}]},{"text":[{"text":"Strength of a forecast","bold":true},{"text":" depends on 3 things: (1) the "},{"text":"quantity and quality of the data","bold":true},{"text":", (2) the "},{"text":"methods","bold":true},{"text":" used to calculate it, (3) the "},{"text":"user's level of competence","bold":true},{"text":"."}]},{"text":[{"text":"Accuracy","bold":true},{"text":" also depends on the validity of the planning data and how far outside circumstances support the plan's assumptions."}]},{"text":[{"text":"Forecast errors:","bold":true},{"text":" "},{"text":"overestimation","bold":true},{"text":" of demand leads to "},{"text":"excess inventory","bold":true},{"text":"; "},{"text":"underestimation","bold":true},{"text":" leads to "},{"text":"short supply","bold":true},{"text":" (stock-outs and lost sales)."}]}]},{"type":"paragraph","text":[{"text":"Significance (why forecast):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Foresee customers' wants and plan accordingly."}]},{"text":[{"text":"Plan production and inventory."}]},{"text":[{"text":"Set prices."}]},{"text":[{"text":"Adjust marketing and sales efforts."}]},{"text":[{"text":"Meet client demand and manage short- and long-term objectives proactively."}]},{"text":[{"text":"Minimise costs of over- or under-stocking."}]},{"text":[{"text":"Reduce lost sales due to stock-outs and fulfil orders on time."}]}]},{"type":"paragraph","text":[{"text":"Importance (4 headline benefits):","bold":true},{"text":" (1) helps prepare your "},{"text":"budget","bold":true},{"text":"; (2) helps determine a "},{"text":"pricing plan","bold":true},{"text":"; (3) "},{"text":"reduces backorders","bold":true},{"text":"; (4) "},{"text":"saves on restocking","bold":true},{"text":" (for example, buying in bulk)."}]},{"type":"paragraph","text":[{"text":"Factors affecting forecasting (6):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Economic conditions:","bold":true},{"text":" GDP, unemployment rate, inflation rate, consumer confidence."}]},{"text":[{"text":"Competition:","bold":true},{"text":" more competition can mean less demand for one firm's product."}]},{"text":[{"text":"Consumer trends:","bold":true},{"text":" a shift towards some products affects demand for others."}]},{"text":[{"text":"Price:","bold":true},{"text":" demand may fall if price rises."}]},{"text":[{"text":"Availability:","bold":true},{"text":" demand may rise if a product is unavailable or in short supply (buyers rush to secure it)."}]},{"text":[{"text":"Advertising:","bold":true},{"text":" demand may rise with effective advertising."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Forecasting "},{"text":"reduces","bold":true},{"text":" uncertainty; it never "},{"text":"removes all","bold":true},{"text":" uncertainty about future sales. An option claiming it does is wrong."}]},{"text":[{"text":"Things that do "},{"text":"not","bold":true},{"text":" affect forecast strength or demand: the colour scheme of the report, the number of directors on the board. Exams use such distractors."}]},{"text":[{"text":"Example: a Lagos cosmetics firm overestimates demand for a new body cream and produces far more than customers buy. Direct result: "},{"text":"excess inventory","bold":true},{"text":", tied-up cash and storage cost. If it had underestimated, shops would run out and customers would switch to rival brands: "},{"text":"lost sales","bold":true},{"text":"."}]},{"text":[{"text":"Past demand is a useful starting point, but planning the future needs more inputs than past figures alone."}]}]}]},{"number":"4.2","title":"Types of forecasting","mustKnow":[{"type":"table","header":[[{"text":"Type"}],[{"text":"Meaning"}]],"rows":[[[{"text":"Short-term"}],[{"text":"Predicts demand for a specific near period (weeks or months, usually up to about a year); methods: statistical analysis, economic models, market research, customer surveys"}]],[[{"text":"Medium-term"}],[{"text":"Covers roughly one to a few years; used for budgets, capacity and sales planning"}]],[[{"text":"Long-term"}],[{"text":"An analytical procedure that predicts demand over a protracted period, to plan and allocate resources and identify opportunities and risks; uses both qualitative and quantitative methods"}]],[[{"text":"Passive"}],[{"text":"Uses "},{"text":"only","bold":true},{"text":" previous sales data to project future demand; suits stable firms"}]],[[{"t$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua125', 15, $study_guide$ext":"Active"}],[{"text":"Uses past demand "},{"text":"plus","bold":true},{"text":" current market trends and other data; common in retail and manufacturing"}]],[[{"text":"Internal"}],[{"text":"A firm forecasts demand for its own goods using past sales, industry trends, economic conditions and customer feedback, to plan production and inventory"}]],[[{"text":"Macro"}],[{"text":"Demand in the "},{"text":"overall economy","bold":true},{"text":", using population, GDP, income and spending"}]],[[{"text":"Micro"}],[{"text":"Demand for a "},{"text":"specific product in a given market","bold":true},{"text":" or small area, using customer behaviour, seasonality, competition, pricing, demographics, local conditions"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Qualitative","bold":true},{"text":" forecasting: based on judgement and opinion (expert opinion, Delphi, sales force composite, surveys of buyers' intentions)."}]},{"text":[{"text":"Quantitative","bold":true},{"text":" forecasting: based on numbers and statistical models (time series, moving averages, exponential smoothing, trend projection, regression, econometric models)."}]},{"text":[{"text":"By subject:","bold":true},{"text":" "},{"text":"demand","bold":true},{"text":" forecasting (what customers will want); "},{"text":"sales","bold":true},{"text":" forecasting (what the firm itself expects to sell); "},{"text":"economic","bold":true},{"text":" forecasting (future GDP, inflation, interest rates, employment); "},{"text":"technological","bold":true},{"text":" forecasting (the direction and speed of technical change)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Time cut-offs vary between books; what matters is the idea: short term = near future, operational plans (staffing, stock); long term = years, strategic plans (new plants, new markets)."}]},{"text":[{"text":"A supermarket in Enugu forecasting the next six weeks for festive staffing and stock is doing "},{"text":"short-term","bold":true},{"text":" forecasting."}]},{"text":[{"text":"Passive vs active trap: "},{"text":"passive = past sales only","bold":true},{"text":"; "},{"text":"active = past demand plus current trends and other data","bold":true},{"text":". Neither is defined by time span or by expert opinion."}]},{"text":[{"text":"Macro vs micro trap: macro is the "},{"text":"whole economy","bold":true},{"text":"; micro is "},{"text":"one product in one market","bold":true},{"text":". A soft drink maker forecasting demand in Surulere alone, using local behaviour, seasonality, competition and pricing, is doing "},{"text":"micro","bold":true},{"text":" forecasting."}]},{"text":[{"text":"Dangote Cement uses long-term forecasts before building a new plant; a Shoprite outlet uses short-term forecasts for Christmas stock. The Central Bank of Nigeria and the National Bureau of Statistics publish economic forecasts and data that firms feed into macro forecasts."}]}]}]},{"number":"4.3","title":"Forecasting techniques","mustKnow":[{"type":"paragraph","text":[{"text":"1. Market research / surveying","bold":true},{"text":" (customer surveys; includes the "},{"text":"survey of buyers' intentions","bold":true},{"text":", asking customers what they plan to buy). Three types:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Sample survey:","bold":true},{"text":" studies the buying behaviour of a small sample of potential customers."}]},{"text":[{"text":"Complete enumeration survey:","bold":true},{"text":" speaks with as many prospective customers as is practical, to collect a larger amount of data."}]},{"text":[{"text":"End-user research:","bold":true},{"text":" asks other businesses (your business customers) what their own customers want."}]}]},{"type":"paragraph","text":[{"text":"2. Statistical approach","bold":true},{"text":" (reliable, often cost-effective):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Trend projection:","bold":true},{"text":" the easiest method; study the past to predict the future."}]},{"text":[{"text":"Regression analysis:","bold":true},{"text":" identifies relationships between demand and external factors (price, time of year, advertising)."}]},{"text":[{"text":"Time series analysis:","bold":true},{"text":" uses historical data; assumes current demand trends will hold true going forward."}]},{"text":[{"text":"Market segmentation:","bold":true},{"text":" identifies which segments are most likely to buy."}]},{"text":[{"text":"Decision trees:","bold":true},{"text":" analyse how different variables can affect demand."}]},{"text":[{"text":"Simulation modelling:","bold":true},{"text":" builds a model of the real system and runs it under different assumptions to see the likely range of outcomes."}]}]},{"type":"paragraph","text":[{"text":"3. Econometric models:","bold":true},{"text":" mathematical models that estimate relationships among economic variables such as prices, demand, supply and consumption; also used to examine the effects of economic policies."}]},{"type":"paragraph","text":[{"text":"4. Sales force composite (\"collective view\"):","bold":true},{"text":" salespeople estimate demand in their own territories; estimates are combined at branch, region or area level into a company forecast. A "},{"text":"bottom-up","bold":true},{"text":" approach."}]},{"type":"paragraph","text":[{"text":"5. Delphi method:","bold":true},{"text":" a "},{"text":"qualitative","bold":true},{"text":" technique; experts are questioned in a "},{"text":"series of rounds","bold":true},{"text":" and their opinions are consolidated into a prediction. Developed by the "},{"text":"RAND Corporation","bold":true},{"text":"; often used with expert opinion."}]},{"type":"paragraph","text":[{"text":"6. Barometric forecasting","bold":true},{"text":" uses "},{"text":"3 indicators","bold":true},{"text":":"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Leading indicators:","bold":true},{"t$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua125', 16, $study_guide$ext":" predict future events (a surge in complaints about delivery delays warns that sales may fall)."}]},{"text":[{"text":"Lagging indicators:","bold":true},{"text":" look back at past outcomes (last month's rise in sales)."}]},{"text":[{"text":"Coincident (coincidental) indicators:","bold":true},{"text":" gauge what is happening now (real-time inventory turnover)."}]}]},{"type":"paragraph","text":[{"text":"7. Expert opinion:","bold":true},{"text":" qualitative forecasting that relies on the judgement of experts."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Why econometrics is hard:","bold":true},{"text":" forecasters can rarely run controlled trials where only one variable changes, so they must estimate effects from messy real-world data."}]},{"text":[{"text":"Sales force composite:","bold":true},{"text":" advantage, salespeople are close to the market and often have first-hand knowledge of customers. Caution, price, campaigns, customer affluence and competition differ by territory, and salespeople may be biased (it is not \"free from bias\"). A beverage firm's reps estimate Lagos 12,500 cartons, Ibadan 8,300, Abeokuta 4,700, Ilorin 3,500: forecast = 12,500 + 8,300 + 4,700 + 3,500 = "},{"text":"29,000 cartons","bold":true},{"text":" (add, do not average)."}]},{"text":[{"text":"Delphi","bold":true},{"text":" experts usually answer separately (often anonymously), receive a summary, and revise in the next round until views converge. This avoids one loud expert dominating."}]},{"text":[{"text":"End-user research example:","bold":true},{"text":" a furniture maker that sells to hotels asks hotel managers what their guests want."}]},{"text":[{"text":"Regression example:","bold":true},{"text":" a paint company measuring how its sales relate to price, season and advertising."}]},{"text":[{"text":"Qualitative vs quantitative trap:","bold":true},{"text":" expert opinion, Delphi and sales force composite are qualitative; moving average, exponential smoothing, trend projection, regression and econometric models are quantitative."}]}]}]},{"number":"4.4","title":"Forecast computations","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Simple moving average (n periods):","bold":true},{"text":" Forecast = (sum of the last n actual values) / n."}]},{"text":[{"text":"Weighted moving average:","bold":true},{"text":" Forecast = sum of (weight x actual) / sum of weights. If weights add to 1, just add the products."}]},{"text":[{"text":"Exponential smoothing:","bold":true},{"text":" F(t+1) = F(t) + alpha x (A(t) - F(t)), same as alpha x A(t) + (1 - alpha) x F(t), with 0 < alpha < 1. Higher alpha = faster response to recent demand. alpha = 1 gives F(t+1) = A(t)."}]},{"text":[{"text":"Constant-change trend:","bold":true},{"text":" average change per year = (last value - first value) / number of intervals; forecast = last value + change x years ahead."}]},{"text":[{"text":"Trend equation:","bold":true},{"text":" Y = a + bX; put in the X for the target year."}]},{"text":[{"text":"Least squares with coded years","bold":true},{"text":" (sum of X = 0): a = (sum of Y) / n; b = (sum of XY) / (sum of X^2)."}]},{"text":[{"text":"Compound growth:","bold":true},{"text":" Forecast = current value x (1 + g)^n."}]},{"text":[{"text":"Forecast error","bold":true},{"text":" = actual - forecast. "},{"text":"MAD","bold":true},{"text":" (mean absolute deviation) = sum of |actual - forecast| / number of periods."}]},{"text":[{"text":"Monitoring:","bold":true},{"text":" compare actual outcomes with forecasts; if inaccurate, adjust the method."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"A. Simple moving average.","bold":true},{"text":" A Surulere bakery sold 420, 450, 480, 510, 470, 500 loaves (January to June). 3-month forecast for July = (510 + 470 + 500) / 3 = 1,480 / 3 = 493.33, about "},{"text":"493","bold":true},{"text":" loaves. Use only the "},{"text":"latest","bold":true},{"text":" 3 months."}]},{"type":"paragraph","text":[{"text":"A Port Harcourt hotel's quarterly revenue (₦ million): 1.2, 1.5, 1.8, 1.4, 1.7. 4-quarter forecast for quarter 6 = (1.5 + 1.8 + 1.4 + 1.7) / 4 = 6.4 / 4 = "},{"text":"₦1.600 million","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Forecast error: sales 30, 34, 38, then actual 40 in period 4. Forecast = (30 + 34 + 38) / 3 = 34; error = 40 - 34 = "},{"text":"6","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"B. Weighted moving average.","bold":true},{"text":" A phone accessories shop sold 200 (March), 220 (April), 250 (May); weights 3 (most recent), 2, 1. Forecast = (3 x 250 + 2 x 220 + 1 x 200) / (3 + 2 + 1) = (750 + 440 + 200) / 6 = 1,390 / 6 = "},{"text":"231.67","bold":true},{"text":" (2 d.p.). Traps: 1,390 forgets to divide; 215.00 puts the weight 3 on the oldest month."}]},{"type":"paragraph","text":[{"text":"With weights 0.5, 0.3, 0.2 on ₦90m (latest), ₦80m, ₦70m: 45 + 24 + 14 = "},{"text":"₦83 million","bold":true},{"text":" (weights sum to 1, so no division)."}]},{"type":"paragraph","text":[{"text":"C. Exponential smoothing.","bold":true},{"text":" Shoe shop: F(May) = 500, A(May) = 540, alpha = 0.2. F(June) = 500 + 0.2 x (540 - 500) = 500 + 8 = "},{"text":"508","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Two steps: alpha = 0.4, F1 = 200, A1 = 220, A2 = 210. F2 = 200 + 0.4 x 20 = 208. F3 = 208 + 0.4 x (210 - 208) = 208 + 0.8 = "},{"text":"208.8","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Finding alpha: F = 1,000, A = 1,200, new F = 1,060. 1,060 - 1,000 = alpha x (1,200 - 1,000), so 60 = 200 x alpha, alpha = "},{"text":"0.3","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Comparing alphas: start 400, actual 500. alpha 0.1 gives 410; alpha 0.5 gives 450; difference "},{"text":"40","bold":true},{"text":". If alpha = 1, F = 300, A = 340 gives next forecast "},{"text":"340","bold":true},{"text":" (the last actual)."}]},{"type":"paragrap$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua125', 17, $study_guide$h","text":[{"text":"D. Trend projection.","bold":true},{"text":" Sales 120, 135, 150, 165 (rising 15 a year): year 5 = 165 + 15 = "},{"text":"180","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Sales ₦80m (2019) and ₦116m (2025): 2019 to 2025 is 6 intervals, so change = 36 / 6 = ₦6m a year. 2027 = 116 + 2 x 6 = "},{"text":"₦128 million","bold":true},{"text":". Trap: dividing by 7 (the number of years) is wrong."}]},{"type":"paragraph","text":[{"text":"Equation Y = 250 + 18X with X = 1 for 2021: 2027 is X = 7, so Y = 250 + 126 = "},{"text":"₦376 million","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"E. Least squares (coded years).","bold":true},{"text":" Sales 2021 to 2025: 40, 44, 50, 54, 62; X = -2, -1, 0, 1, 2."}]},{"type":"table","header":[[{"text":"Year"}],[{"text":"X"}],[{"text":"Y"}],[{"text":"XY"}],[{"text":"X^2"}]],"rows":[[[{"text":"2021"}],[{"text":"-2"}],[{"text":"40"}],[{"text":"-80"}],[{"text":"4"}]],[[{"text":"2022"}],[{"text":"-1"}],[{"text":"44"}],[{"text":"-44"}],[{"text":"1"}]],[[{"text":"2023"}],[{"text":"0"}],[{"text":"50"}],[{"text":"0"}],[{"text":"0"}]],[[{"text":"2024"}],[{"text":"1"}],[{"text":"54"}],[{"text":"54"}],[{"text":"1"}]],[[{"text":"2025"}],[{"text":"2"}],[{"text":"62"}],[{"text":"124"}],[{"text":"4"}]],[[{"text":"Total"}],[{"text":"0"}],[{"text":"250"}],[{"text":"54"}],[{"text":"10"}]]]},{"type":"paragraph","text":[{"text":"a = 250 / 5 = 50; b = 54 / 10 = 5.4. 2026 is X = 3: Y = 50 + 5.4 x 3 = "},{"text":"₦66.20 million","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"F. Compound growth.","bold":true},{"text":" ₦50m growing 8% a year: 50 x 1.08^2 = 50 x 1.1664 = "},{"text":"₦58.32 million","bold":true},{"text":". Trap: ₦58.00m adds 8% simple growth twice."}]},{"type":"paragraph","text":[{"text":"G. MAD.","bold":true},{"text":" Actual 100, 110, 95, 105; forecast 98, 104, 101, 103. Errors: 2, 6, -6, 2. Absolute: 2, 6, 6, 2; total 16. MAD = 16 / 4 = "},{"text":"4.00","bold":true},{"text":". Trap: averaging signed errors gives 1.00, which lets positive and negative errors cancel."}]}]},{"number":"4.5","title":"Steps, challenges and implications","mustKnow":[{"type":"paragraph","text":[{"text":"Steps in forecasting:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Understand the problem and set the objective (what, for whom, how far ahead)."}]},{"text":[{"text":"Choose the best forecasting method(s)."}]},{"text":[{"text":"Collect and check the data."}]},{"text":[{"text":"Analyse the data and make the forecast."}]},{"text":[{"text":"Use the forecast in plans (production, inventory, pricing, budget)."}]},{"text":[{"text":"Monitor: compare actual results with forecasts and adjust the method if inaccurate."}]}]},{"type":"paragraph","text":[{"text":"Forecasting challenges (7):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Lack of data."}]},{"text":[{"text":"Over-reliance on past data."}]},{"text":[{"text":"Limited visibility into the future."}]},{"text":[{"text":"Inaccurate demand models."}]},{"text":[{"text":"Poor forecasting processes."}]},{"text":[{"text":"Insufficient resources."}]},{"text":[{"text":"Unpredictable external factors."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Unpredictable external factors in Nigeria include sudden exchange-rate swings, fuel price changes and policy shifts; these can upset even a sound model."}]},{"text":[{"text":"Over-reliance on past data fails when conditions change, for example when a new competitor such as a cheaper rival brand enters."}]},{"text":[{"text":"Implications for managers: use more than one method and compare; update forecasts often; build safety stock where errors are costly; treat a forecast as a planning tool, not a guarantee. \"Having too many accurate and complete data sources\" is "},{"text":"not","bold":true},{"text":" a challenge."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Demand forecasting anticipates future demand; strength depends on data, method and user competence."}]},{"text":[{"text":"Overestimate gives excess inventory; underestimate gives stock-outs and lost sales."}]},{"text":[{"text":"6 factors: economic conditions, competition, consumer trends, price, availability, advertising."}]},{"text":[{"text":"Passive = past sales only; active adds current trends; macro = whole economy; micro = one product, one market."}]},{"text":[{"text":"Surveys: sample, complete enumeration, end-user research. Delphi = experts in rounds (RAND)."}]},{"text":[{"text":"Barometric: leading (future), lagging (past), coincident (now)."}]},{"text":[{"text":"Moving average: latest n values / n; weighted: divide by sum of weights."}]},{"text":[{"text":"Exponential smoothing: F(t+1) = F(t) + alpha(A(t) - F(t)); higher alpha reacts faster."}]},{"text":[{"text":"MAD = average of absolute errors; error = actual - forecast."}]},{"text":[{"text":"7 challenges, from lack of data to unpredictable external factors."}]}]}],"theory":{"itemId":"ef914fd9-9610-5ce7-b1de-3f701eff4930","question":[{"type":"paragraph","text":[{"text":"A Kano rice seller sold 60, 64, 70, 66 and 72 bags in weeks 1 to 5. Find the 4-week simple moving average forecast for week 6. Then, using exponential smoothing with alpha = 0.5 and a week-5 forecast of 68 bags, find the week-6 forecast."}]}]},"practice":[{"topic":"Business Forecasting","named":false}]}},{"kind":"note","itemId":"dfb1e3d7-8b28-5376-b1cc-147144406191","sourceKey":"guide-topic:5","position":5,"payload":{"title":"Cost Analysis: Short Run and Long Run","body":"The cost concepts and how to classify costs; the short-run cost measures and their formulas; how to compute them from tables and cost functions; the shapes of the short-run cost curves and how they relate; the law of diminishing returns; long-run costs, economies and diseconomies of scale and the LRAC curve; break-even, shut-down and exit rules; what $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua125', 18, $study_guide$all this means for managers.","noteType":"guide_topic","number":5,"mustKnow":[{"text":"The cost concepts and how to classify costs; the short-run cost measures and their formulas; how to compute them from tables and cost functions; the shapes of the short-run cost curves and how they relate; the law of diminishing returns; long-run costs, economies and diseconomies of scale and the LRAC curve; break-even, shut-down and exit rules; what all this means for managers."}],"lessons":[{"number":"5.1","title":"Cost concepts and classification","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Short run:","bold":true},{"text":" a period in which "},{"text":"at least one factor of production is fixed","bold":true},{"text":" (e.g. the size of the factory). So the firm has both fixed and variable costs."}]},{"text":[{"text":"Long run:","bold":true},{"text":" a period long enough for "},{"text":"all factors to be varied","bold":true},{"text":". "},{"text":"All costs are variable; there are no fixed costs.","bold":true},{"text":" The long run is not a set number of months; it depends on how long it takes to change every input."}]},{"text":[{"text":"In the short run, costs are classified into "},{"text":"fixed costs and variable costs","bold":true},{"text":"."}]},{"text":[{"text":"Fixed cost:","bold":true},{"text":" a cost that does "},{"text":"not change with the level of output","bold":true},{"text":" in the short run and "},{"text":"must be paid even when output is zero","bold":true},{"text":". It "},{"text":"remains constant in total","bold":true},{"text":" when activity changes (but falls "},{"text":"per unit","bold":true},{"text":" as output rises). Examples: rent, insurance premiums, licence fees, interest on loans, salaries of managers."}]},{"text":[{"text":"Variable cost:","bold":true},{"text":" a cost that "},{"text":"varies in total in proportion to changes in the level of activity","bold":true},{"text":". It "},{"text":"remains constant per unit","bold":true},{"text":" at various levels of activity. Examples: raw materials (flour per batch), fuel per trip, packaging, piece-rate wages."}]},{"text":[{"text":"Mixed (semi-variable) cost:","bold":true},{"text":" contains "},{"text":"a fixed element and a variable element","bold":true},{"text":", e.g. an electricity bill with a fixed monthly charge plus a charge per unit used."}]},{"text":[{"text":"Relevant range:","bold":true},{"text":" the "},{"text":"range of activity levels over which the firm expects to operate","bold":true},{"text":"; within it, the fixed/variable behaviour above holds."}]}]},{"type":"table","header":[[{"text":"Cost"}],[{"text":"In total, as output rises"}],[{"text":"Per unit, as output rises"}]],"rows":[[[{"text":"Fixed"}],[{"text":"stays the same"}],[{"text":"falls"}]],[[{"text":"Variable"}],[{"text":"rises in proportion"}],[{"text":"stays the same"}]]]},{"type":"paragraph","text":[{"text":"Other cost concepts:"}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Explicit cost:","bold":true},{"text":" an out-of-pocket expense paid in cash and recorded in the accounts, e.g. rent, salaries, operating expenses."}]},{"text":[{"text":"Implicit (imputed) cost:","bold":true},{"text":" no cash changes hands; it is the opportunity cost of resources the owner already has, e.g. the salary an owner gives up to run the business."}]},{"text":[{"text":"Opportunity cost:","bold":true},{"text":" the benefit given up from the next best alternative when one option is chosen."}]},{"text":[{"text":"Sunk cost:","bold":true},{"text":" money already spent in the past that cannot be recovered, e.g. machinery already bought."}]},{"text":[{"text":"Historical cost:","bold":true},{"text":" the "},{"text":"actual cost incurred at the time the asset was acquired","bold":true},{"text":"."}]},{"text":[{"text":"Replacement cost:","bold":true},{"text":" the cost of replacing the asset at "},{"text":"today's prices","bold":true},{"text":"."}]},{"text":[{"text":"Marginal cost:","bold":true},{"text":" the cost of producing one extra unit."}]},{"text":[{"text":"Incremental (differential) cost:","bold":true},{"text":" the extra cost of a decision, often for a change of more than one unit at a time (e.g. adding a new shift)."}]},{"text":[{"text":"Relevant cost:","bold":true},{"text":" a cost that "},{"text":"differs between the alternatives","bold":true},{"text":" being considered. Rule: "},{"text":"only future costs that differ between the alternatives are relevant.","bold":true}]},{"text":[{"text":"Irrelevant cost:","bold":true},{"text":" a cost that "},{"text":"does not affect a decision","bold":true},{"text":" (sunk costs, and future costs that are the same under every option)."}]},{"text":[{"text":"Avoidable cost:","bold":true},{"text":" a cost that can be saved by not taking a particular option."}]},{"text":[{"text":"Private cost:","bold":true},{"text":" the cost paid by the "},{"text":"individual or firm directly involved","bold":true},{"text":" in producing or consuming a good."}]},{"text":[{"text":"External cost:","bold":true},{"text":" the cost borne by "},{"text":"people not directly involved","bold":true},{"text":", e.g. residents affected by a factory's pollution."}]},{"text":[{"text":"Social cost = private cost + external cost.","bold":true}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"For a Lagos bread bakery, "},{"text":"flour used in each batch","bold":true},{"text":" is variable; monthly rent, the annual fire insurance premium and the manager's salary are fixed. For a transport company, "},{"text":"diesel used on each trip","bold":true},{"text":" is variable (so it is NOT a fixed cost); rent on the park, annual vehicle licence fees and interest on a loan for buses are fixed."}]},{"text":[{"text":"Trap: \"constant "},{"text":"per unit","bold":true},{"text":"\" describes a "},{"text":"variable","bold":true},{"text":" cost; \"constant "},{"text":"in total","bold":true},{"text":"\" descr$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua125', 19, $study_guide$ibes a "},{"text":"fixed","bold":true},{"text":" cost. Exams swap these two phrases."}]},{"text":[{"text":"Trap: a variable cost does "},{"text":"not","bold":true},{"text":" \"vary per unit at every level of activity\", and is not \"a cost that occurs at various times of the year\"."}]},{"text":[{"text":"Past costs are "},{"text":"never","bold":true},{"text":" relevant to a future decision; not all future costs are relevant (only those that differ); fixed costs that stay the same under every option are irrelevant. Example: Dangote Cement deciding whether to open a new line ignores the ₦50 million already spent on a feasibility study (sunk) and counts only the extra future costs and revenues the new line would bring."}]},{"text":[{"text":"If a cement plant in Ogun State pays ₦5 million for raw materials and energy (private cost) while its dust costs nearby households ₦2 million in health care and cleaning (external cost), the social cost is ₦5 million + ₦2 million = ₦7 million."}]}]}]},{"number":"5.2","title":"Short-run cost measures and computations","mustKnow":[{"type":"paragraph","text":[{"text":"Formulas (Q = output):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"TC = TFC + TVC","bold":true},{"text":" (total cost)"}]},{"text":[{"text":"TFC = TC at zero output","bold":true},{"text":" (because TVC is 0 when Q = 0)"}]},{"text":[{"text":"TVC = TC − TFC","bold":true}]},{"text":[{"text":"AFC = TFC / Q","bold":true}]},{"text":[{"text":"AVC = TVC / Q","bold":true}]},{"text":[{"text":"ATC = TC / Q = AFC + AVC","bold":true}]},{"text":[{"text":"MC = change in TC / change in Q","bold":true},{"text":" (= change in TVC / change in Q, because TFC does not change)"}]},{"text":[{"text":"From averages: "},{"text":"TC = ATC × Q","bold":true},{"text":", "},{"text":"TVC = AVC × Q","bold":true},{"text":", "},{"text":"TFC = AFC × Q","bold":true}]},{"text":[{"text":"From marginal costs: "},{"text":"TC = TFC + sum of the MCs","bold":true}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Marginal cost:","bold":true},{"text":" the "},{"text":"addition to total cost from producing one more unit of output","bold":true},{"text":" (the change in total cost from a one-unit change in output)."}]},{"text":[{"text":"In the short run, both "},{"text":"TVC and TC depend on output","bold":true},{"text":"; TFC does not."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example 1: a full cost table.","bold":true},{"text":" A sachet-water firm has these costs:"}]},{"type":"table","header":[[{"text":"Q"}],[{"text":"TC (₦)"}],[{"text":"TVC (₦)"}],[{"text":"AFC (₦)"}],[{"text":"AVC (₦)"}],[{"text":"ATC (₦)"}],[{"text":"MC (₦)"}]],"rows":[[[{"text":"0"}],[{"text":"1,000"}],[{"text":"0"}],[{"text":"–"}],[{"text":"–"}],[{"text":"–"}],[{"text":"–"}]],[[{"text":"1"}],[{"text":"1,400"}],[{"text":"400"}],[{"text":"1,000"}],[{"text":"400"}],[{"text":"1,400"}],[{"text":"400"}]],[[{"text":"2"}],[{"text":"1,700"}],[{"text":"700"}],[{"text":"500"}],[{"text":"350"}],[{"text":"850"}],[{"text":"300"}]],[[{"text":"3"}],[{"text":"1,900"}],[{"text":"900"}],[{"text":"333.33"}],[{"text":"300"}],[{"text":"633.33"}],[{"text":"200"}]],[[{"text":"4"}],[{"text":"2,200"}],[{"text":"1,200"}],[{"text":"250"}],[{"text":"300"}],[{"text":"550"}],[{"text":"300"}]],[[{"text":"5"}],[{"text":"2,700"}],[{"text":"1,700"}],[{"text":"200"}],[{"text":"340"}],[{"text":"540"}],[{"text":"500"}]],[[{"text":"6"}],[{"text":"3,400"}],[{"text":"2,400"}],[{"text":"166.67"}],[{"text":"400"}],[{"text":"566.67"}],[{"text":"700"}]]]},{"type":"paragraph","text":[{"text":"(Figures rounded to 2 decimal places.)"}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Step 1: TFC = TC at Q = 0 = "},{"text":"₦1,000","bold":true},{"text":"."}]},{"text":[{"text":"Step 2: TVC at 3 units = 1,900 − 1,000 = "},{"text":"₦900","bold":true},{"text":"."}]},{"text":[{"text":"Step 3: AFC at 4 = 1,000 / 4 = "},{"text":"₦250","bold":true},{"text":". AVC at 5 = 1,700 / 5 = "},{"text":"₦340","bold":true},{"text":". ATC at 3 = 1,900 / 3 = "},{"text":"₦633.33","bold":true},{"text":"."}]},{"text":[{"text":"Step 4: MC of the 4th unit = TC(4) − TC(3) = 2,200 − 1,900 = "},{"text":"₦300","bold":true},{"text":". Note: the MC of a unit is a difference, not the total cost at that unit."}]},{"text":[{"text":"Step 5: MC is lowest over the "},{"text":"3rd unit","bold":true},{"text":" (₦200). AVC is lowest at "},{"text":"₦300","bold":true},{"text":" (3 and 4 units). ATC is lowest at "},{"text":"5 units","bold":true},{"text":" (₦540)."}]},{"text":[{"text":"Check: at the 4th unit MC = AVC = ₦300 (MC meets AVC at its minimum); the 5th unit's MC (₦500) is below ATC at 4 (₦550), so ATC is still falling; the 6th unit's MC (₦700) is above ₦540, so ATC rises."}]}]},{"type":"paragraph","text":[{"text":"Worked example 2: from averages and totals.","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"AFC ₦12 and AVC ₦30 at 1,000 units: ATC = 12 + 30 = ₦42, so TC = 42 × 1,000 = "},{"text":"₦42,000","bold":true},{"text":"."}]},{"text":[{"text":"ATC ₦90 and AFC ₦25: AVC = 90 − 25 = "},{"text":"₦65","bold":true},{"text":"."}]},{"text":[{"text":"AFC ₦25 at 600 copies, plant unchanged, output rises to 1,000: TFC = 25 × 600 = ₦15,000; new AFC = 15,000 / 1,000 = "},{"text":"₦15","bold":true},{"text":"."}]},{"text":[{"text":"ATC ₦1,100 at 200 units and TFC ₦40,000: TC = 1,100 × 200 = ₦220,000; TVC = 220,000 − 40,000 = "},{"text":"₦180,000","bold":true},{"text":"."}]},{"text":[{"text":"TC ₦2,000 at zero output and ₦8,000 at 50 units: TVC = 8,000 − 2,000 = ₦6,000; AVC = 6,000 / 50 = "},{"text":"₦120","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Worked example 3: marginal cost over a range and from averages.","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"TC rises from ₦80,000 to ₦95,000 as output rises from 100 to 150 bags: MC = 15,000 / 50 = "},{"text":"₦300 per bag","bold":true},{"text":". Divide by the chang$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua125', 20, $study_guide$e in output, not by the new output."}]},{"text":[{"text":"AVC is ₦1,800 at 5 pairs and ₦1,900 at 6 pairs: TVC(5) = 9,000; TVC(6) = 11,400; MC of the 6th pair = "},{"text":"₦2,400","bold":true},{"text":". Never just subtract the averages."}]},{"text":[{"text":"ATC is ₦60 at 7 units and ₦58 at 8 units: TC(7) = 420; TC(8) = 464; MC of the 8th = "},{"text":"₦44","bold":true},{"text":"."}]},{"text":[{"text":"TFC ₦400 and MCs of the 1st, 2nd and 3rd units ₦100, ₦80, ₦90: TC(3) = 400 + 100 + 80 + 90 = "},{"text":"₦670","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Worked example 4: cost functions.","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Linear: TC = 20,000 + 900Q. TFC = ₦20,000 (the constant); AVC = MC = "},{"text":"₦900","bold":true},{"text":" at every output. At Q = 40: ATC = 20,000/40 + 900 = 500 + 900 = "},{"text":"₦1,400","bold":true},{"text":"."}]},{"text":[{"text":"Quadratic: TC = 500 + 30Q + 3Q^2. TFC = 500; TVC = 30Q + 3Q^2. At Q = 8: TVC = 240 + 192 = 432, so AVC = 432 / 8 = "},{"text":"₦54","bold":true},{"text":"; TC = 932, ATC = 932 / 8 = "},{"text":"₦116.50","bold":true},{"text":". MC of the 8th unit = TC(8) − TC(7) = 932 − 857 = "},{"text":"₦75","bold":true},{"text":"."}]}]}]},{"number":"5.3","title":"Short-run cost curves and the law of diminishing returns","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Law of diminishing returns (law of variable proportions):","bold":true},{"text":" when more and more units of a variable factor are added to a fixed factor, the extra output from each additional unit eventually falls. So, beyond a point, "},{"text":"MC rises","bold":true},{"text":"."}]},{"text":[{"text":"The "},{"text":"short-run","bold":true},{"text":" average cost curves (AVC, ATC) and MC are "},{"text":"U-shaped mainly because of the law of diminishing returns","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Shapes:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"TFC:","bold":true},{"text":" a "},{"text":"horizontal straight line","bold":true},{"text":"."}]},{"text":[{"text":"TVC:","bold":true},{"text":" starts from the "},{"text":"origin","bold":true},{"text":" and rises."}]},{"text":[{"text":"TC:","bold":true},{"text":" starts at the level of fixed cost and lies "},{"text":"above TVC by exactly TFC at every output","bold":true},{"text":" (the two curves are parallel)."}]},{"text":[{"text":"AFC:","bold":true},{"text":" "},{"text":"slopes downward throughout and never touches the output axis","bold":true},{"text":" (a fixed sum spread over more units)."}]},{"text":[{"text":"AVC, ATC, MC:","bold":true},{"text":" "},{"text":"U-shaped","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Relationships:"}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"MC cuts AVC and ATC at their minimum points.","bold":true}]},{"text":[{"text":"MC below an average → that average is falling. MC above an average → that average is rising.","bold":true}]},{"text":[{"text":"Vertical gap between ATC and AVC = AFC","bold":true},{"text":", and it "},{"text":"gets smaller as output rises","bold":true},{"text":" because AFC falls."}]},{"text":[{"text":"The minimum of ATC comes at a "},{"text":"higher output","bold":true},{"text":" than the minimum of AVC."}]},{"text":[{"text":"Average cost falls until the "},{"text":"optimum scale","bold":true},{"text":", where "},{"text":"MC = AC","bold":true},{"text":", then rises: a "},{"text":"U-shape","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Picture a small Indomie noodle stall with one cooker (fixed). Adding a second and third worker raises output a lot; a sixth worker mostly gets in the way. Each extra worker adds less output, so each extra plate costs more: MC rises. David Ricardo applied this law to farming on a fixed area of land."}]},{"text":[{"text":"Think of your CGPA: if your next result (marginal) is below your average, the average falls; if above, it rises. The same logic makes MC pass through the lowest point of AVC and ATC."}]},{"text":[{"text":"Trap: MC cuts AVC at its "},{"text":"minimum","bold":true},{"text":", never its maximum. Trap: AFC is not U-shaped and not horizontal; TFC is the horizontal one."}]},{"text":[{"text":"Input prices and the curves:","bold":true},{"text":" a rise in the price of a variable input (flour, fuel) shifts "},{"text":"MC, AVC and ATC","bold":true},{"text":" upward but "},{"text":"not AFC","bold":true},{"text":". If a bakery uses 2 bags of flour per batch and flour rises by ₦3,000 a bag, MC per batch rises by 2 × 3,000 = "},{"text":"₦6,000","bold":true},{"text":". A rise in a fixed cost (rent) shifts "},{"text":"AFC and ATC","bold":true},{"text":" but "},{"text":"not MC or AVC","bold":true},{"text":": if rent rises from ₦200,000 to ₦260,000 and MC at 1,000 units was ₦150, MC stays "},{"text":"₦150","bold":true},{"text":"."}]}]}]},{"number":"5.4","title":"Long-run costs, economies and diseconomies of scale","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Economies of scale:","bold":true},{"text":" the "},{"text":"fall in long-run average cost","bold":true},{"text":" a firm enjoys as it increases the scale of its operations."}]},{"text":[{"text":"Diseconomies of scale:","bold":true},{"text":" the "},{"text":"rise in LRAC","bold":true},{"text":" when a firm grows beyond its efficient size."}]},{"text":[{"text":"Constant returns to scale:","bold":true},{"text":" LRAC stays the same as scale rises; the LRAC curve is "},{"text":"horizontal","bold":true},{"text":" over that range."}]},{"text":[{"text":"LRAC curve:","bold":true},{"text":" shows the lowest average cost of producing each output when all inputs can be varied. Also called the "},{"text":"planning curve","bold":true},{"text":" or "},{"text":"envelope curve","bold":true},{"text":", because it is an "},{"text":"envelope of a series of short-run a$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua125', 21, $study_guide$verage cost curves","bold":true},{"text":" (one SRAC for each plant size)."}]},{"text":[{"text":"The "},{"text":"LRAC","bold":true},{"text":" is U-shaped because of "},{"text":"economies of scale at low outputs followed by diseconomies of scale at high outputs","bold":true},{"text":" (not diminishing returns, which is the short-run reason)."}]},{"text":[{"text":"LRAC = LTC / Q.","bold":true}]}]},{"type":"paragraph","text":[{"text":"Internal economies of scale","bold":true},{"text":" (arise inside the firm as it grows):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Technical:","bold":true},{"text":" bigger, more efficient machines; specialisation; larger production runs."}]},{"text":[{"text":"Marketing (bulk-buying):","bold":true},{"text":" discounts for buying inputs in large quantities; advertising spread over more output."}]},{"text":[{"text":"Financial:","bold":true},{"text":" big firms borrow more cheaply because lenders see them as less risky."}]},{"text":[{"text":"Managerial:","bold":true},{"text":" hiring specialist managers for each function."}]},{"text":[{"text":"Risk-bearing:","bold":true},{"text":" spreading risk over many products and markets (diversification)."}]}]},{"type":"paragraph","text":[{"text":"External economies of scale:","bold":true},{"text":" cost savings to "},{"text":"every firm","bold":true},{"text":" in an industry when the industry grows or clusters in one place: a pool of skilled labour, specialist suppliers, better roads and services, shared information."}]},{"type":"paragraph","text":[{"text":"Diseconomies of scale:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Managerial:","bold":true},{"text":" too many layers of management; slow decisions, poor communication and coordination."}]},{"text":[{"text":"Labour:","bold":true},{"text":" workers feel remote and less motivated."}]},{"text":[{"text":"External:","bold":true},{"text":" congestion and rising input prices when an industry grows too large in one place."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Financial economies:","bold":true},{"text":" Dangote Cement gets bank loans at lower interest rates than a small block-maker. "},{"text":"Bulk-buying (marketing) economies:","bold":true},{"text":" a large supermarket chain buying rice by the trailer-load at a big discount per bag. "},{"text":"External economies:","bold":true},{"text":" electronics and phone dealers clustered at Computer Village, Ikeja, where skilled technicians and specialist suppliers cut every firm's costs."}]},{"text":[{"text":"Diseconomies example:","bold":true},{"text":" a company so large that a simple approval passes through many layers, communication slows and LRAC rises."}]},{"text":[{"text":"Trap: the "},{"text":"short-run","bold":true},{"text":" U-shape is due to "},{"text":"diminishing returns","bold":true},{"text":"; the "},{"text":"long-run","bold":true},{"text":" U-shape is due to "},{"text":"economies then diseconomies of scale","bold":true},{"text":". Exams swap them."}]}]},{"type":"paragraph","text":[{"text":"Worked example 5: reading scale from a long-run cost table.","bold":true}]},{"type":"table","header":[[{"text":"Q (units)"}],[{"text":"LTC (₦)"}],[{"text":"LRAC = LTC / Q (₦)"}]],"rows":[[[{"text":"1,000"}],[{"text":"80,000"}],[{"text":"80"}]],[[{"text":"2,000"}],[{"text":"140,000"}],[{"text":"70"}]],[[{"text":"3,000"}],[{"text":"180,000"}],[{"text":"60"}]],[[{"text":"4,000"}],[{"text":"240,000"}],[{"text":"60"}]],[[{"text":"5,000"}],[{"text":"330,000"}],[{"text":"66"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"1,000 to 3,000 units: LRAC falls (80 → 70 → 60): "},{"text":"economies of scale","bold":true},{"text":"."}]},{"text":[{"text":"3,000 to 4,000 units: LRAC constant at 60: "},{"text":"constant returns to scale","bold":true},{"text":"."}]},{"text":[{"text":"4,000 to 5,000 units: LRAC rises to ₦66: "},{"text":"diseconomies of scale","bold":true},{"text":"."}]},{"text":[{"text":"Always compute LRAC first; LTC itself always rises with output, so it cannot tell you the answer."}]}]}]},{"number":"5.5","title":"Costs in decisions: break-even, shut-down, exit and implications","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Break-even point:","bold":true},{"text":" the level of activity at which "},{"text":"total revenue equals total cost","bold":true},{"text":", so "},{"text":"profit is zero","bold":true},{"text":". Here "},{"text":"total contribution margin equals total fixed cost","bold":true},{"text":"."}]},{"text":[{"text":"Contribution per unit = Price − AVC.","bold":true}]},{"text":[{"text":"Break-even output = TFC / (Price − AVC).","bold":true}]},{"text":[{"text":"Break-even revenue = break-even output × Price","bold":true},{"text":" (or TFC / contribution ratio, where contribution ratio = (P − AVC) / P)."}]},{"text":[{"text":"Output for a target profit = (TFC + target profit) / (Price − AVC).","bold":true}]},{"text":[{"text":"Profit = TR − TC = (P × Q) − TFC − (AVC × Q).","bold":true}]},{"text":[{"text":"Short-run shut-down rule:","bold":true},{"text":" shut down if "},{"text":"total revenue cannot cover total variable cost","bold":true},{"text":", i.e. "},{"text":"price is below the minimum of AVC","bold":true},{"text":". The "},{"text":"shut-down point","bold":true},{"text":" is minimum AVC."}]},{"text":[{"text":"Long-run exit rule:","bold":true},{"text":" leave the market if "},{"text":"revenue is less than total cost","bold":true},{"text":" (price below ATC), because in the long run there are no fixed costs left to cover."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example 6: break-even and profit.","bold":true},{"text":" A poultry farm sells crates of eggs at ₦1,500, AVC is ₦900 and TFC is ₦180,000."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Contribution per crate = 1,500 − 900 = ₦600."}]},{"text":[{"text":"Break-even output = 180,00$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua125', 22, $study_guide$0 / 600 = "},{"text":"300 crates","bold":true},{"text":"."}]},{"text":[{"text":"Break-even revenue = 300 × 1,500 = "},{"text":"₦450,000","bold":true},{"text":". Check: contribution ratio = 600 / 1,500 = 0.4; 180,000 / 0.4 = ₦450,000."}]},{"text":[{"text":"Output for a profit of ₦120,000 = (180,000 + 120,000) / 600 = "},{"text":"500 crates","bold":true},{"text":"."}]},{"text":[{"text":"Profit at 800 crates = 800 × 1,500 − 180,000 − 800 × 900 = 1,200,000 − 180,000 − 720,000 = "},{"text":"₦300,000","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Why the shut-down rule works.","bold":true},{"text":" In the short run, the fixed cost must be paid even at zero output. If a firm is making a loss but its revenue covers TVC and part of TFC, producing loses less than shutting down, so it keeps going. Only when price falls below minimum AVC does every unit add to the loss. In Worked example 1, minimum AVC is ₦300, so a price-taking firm would stop producing in the short run at any price below "},{"text":"₦300","bold":true},{"text":". Trap: a firm does not shut down simply because it makes \"any loss\" or because fixed costs exceed revenue; and MC above AVC is normal, not a shut-down signal."}]},{"type":"paragraph","text":[{"text":"Implications for managers:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Use only "},{"text":"relevant (future, differing) costs","bold":true},{"text":" in decisions; ignore sunk costs."}]},{"text":[{"text":"Watch "},{"text":"MC","bold":true},{"text":" when deciding whether to expand output; expand while each extra unit's revenue covers its MC."}]},{"text":[{"text":"Spread fixed costs over more output to cut AFC and ATC (why MTN and Globacom chase more subscribers on the same network)."}]},{"text":[{"text":"Choose a plant size on the lowest part of the LRAC; grow to gain economies of scale, but guard against diseconomies with good structure and communication."}]},{"text":[{"text":"Know the "},{"text":"break-even","bold":true},{"text":" and "},{"text":"shut-down","bold":true},{"text":" prices before setting prices or cutting output."}]},{"text":[{"text":"Consider "},{"text":"external (social) costs","bold":true},{"text":", which may lead to regulation, levies or reputation damage."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Short run: at least one factor fixed; long run: all costs variable."}]},{"text":[{"text":"Fixed cost: constant in total, falls per unit; variable cost: varies in total, constant per unit; mixed = both."}]},{"text":[{"text":"TC = TFC + TVC; AFC = TFC/Q; AVC = TVC/Q; ATC = AFC + AVC; MC = change in TC / change in Q."}]},{"text":[{"text":"TFC horizontal; AFC falls forever; AVC, ATC, MC U-shaped; MC cuts AVC and ATC at their minimum."}]},{"text":[{"text":"Short-run U-shape: diminishing returns. Long-run U-shape: economies then diseconomies of scale."}]},{"text":[{"text":"LRAC = planning (envelope) curve; horizontal under constant returns."}]},{"text":[{"text":"Relevant costs are future and differ between alternatives; sunk costs are irrelevant."}]},{"text":[{"text":"Social cost = private cost + external cost."}]},{"text":[{"text":"Break-even Q = TFC / (P − AVC); shut down if P < minimum AVC; exit in the long run if TR < TC."}]}]}],"theory":{"itemId":"00a2f083-5476-5812-9189-babd4a5c029c","question":[{"type":"paragraph","text":[{"text":"A firm's TFC is ₦200. Its TVC at 1, 2, 3 and 4 units is ₦80, ₦140, ₦210 and ₦320. Find AVC, ATC and MC at each output, and the lowest price at which a price-taking firm would keep producing in the short run."}]}]},"practice":[{"topic":"Cost Analysis: Short Run and Long Run","named":false}]}},{"kind":"note","itemId":"7e2fd184-b815-5acf-b4cb-a537c0f85bcc","sourceKey":"guide-topic:6","position":6,"payload":{"title":"Market Segmentation","body":"Why firms analyse customer needs and segment; the meaning of market segmentation and a segment; the 4 bases for consumer markets and their variables; the 5 requirements for effective segments; targeting (evaluating segments and the targeting strategies); positioning; the steps (segmentation, targeting, positioning); benefits, costs and managerial implications, including segment pricing; and segment-size computations.","noteType":"guide_topic","number":6,"mustKnow":[{"text":"Why firms analyse customer needs and segment; the meaning of market segmentation and a segment; the 4 bases for consumer markets and their variables; the 5 requirements for effective segments; targeting (evaluating segments and the targeting strategies); positioning; the steps (segmentation, targeting, positioning); benefits, costs and managerial implications, including segment pricing; and segment-size computations."}],"lessons":[{"number":"6.1","title":"Need analysis and the meaning of segmentation","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Need analysis:","bold":true},{"text":" studying what different customers need and want, how they buy and why, so the firm can see that one market is really many groups with different needs."}]},{"text":[{"text":"Market segmentation:","bold":true},{"text":" dividing a total market into distinct groups of buyers who have different needs, characteristics or behaviours, and who might require separate products or marketing programmes."}]},{"text":[{"text":"Market segment:","bold":true},{"text":" a group of consumers who respond in a similar way to a given set of marketing efforts."}]},{"text":[{"text":"Mass (undifferentiated) marketing:","bold":true},{"text":" treating the whole market as one and offering one product to all; the opposite of segmentation."}]},{"text":[{"text":"Origin:","bold":true},{"text":" the concept of market segmentation was introduced by "},{"text":"Wendell Smith","bold":true},{"text":" (1956)."}]}]},{"type":"paragraph","text":[{"text":"Why firms segment (need for segmentation):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua125', 23, $study_guide$[{"text":"Buyers differ in needs, incomes, tastes, locations and buying habits; one offer rarely satisfies all."}]},{"text":[{"text":"Resources are limited, so a firm must choose where to compete."}]},{"text":[{"text":"It lets the firm match products and the marketing mix more closely to customers' needs."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Think of the Nigerian noodle market. Some buyers want the cheapest pack, some want bigger packs for the family, some want new flavours. Indomie offers different pack sizes and flavours because it has analysed these needs."}]},{"text":[{"text":"Segmentation is not the same as "},{"text":"positioning","bold":true},{"text":" (creating a place in consumers' minds) or "},{"text":"market penetration","bold":true},{"text":" (selling more of an existing product in an existing market). Exams swap these terms."}]},{"text":[{"text":"A segment is a "},{"text":"group","bold":true},{"text":" responding similarly; it is not one large customer, nor the number of firms in an industry, nor the market share of the largest firm."}]}]}]},{"number":"6.2","title":"Bases for segmenting consumer markets","mustKnow":[{"type":"paragraph","text":[{"text":"The "},{"text":"4 major bases","bold":true},{"text":":"}]},{"type":"table","header":[[{"text":"Basis"}],[{"text":"Divides buyers by"}],[{"text":"Typical variables"}]],"rows":[[[{"text":"Geographic"}],[{"text":"Where they are"}],[{"text":"Nations, regions, states, cities, neighbourhoods, city size, population density, climate"}]],[[{"text":"Demographic"}],[{"text":"Who they are (measurable population traits)"}],[{"text":"Age and life-cycle stage, gender, income, family size, occupation, education, religion, ethnicity, generation"}]],[[{"text":"Psychographic"}],[{"text":"How they live and think"}],[{"text":"Lifestyle, personality, values (and social class)"}]],[[{"text":"Behavioural"}],[{"text":"How they act towards the product"}],[{"text":"Occasions, benefits sought, user status, usage rate, loyalty status"}]]]},{"type":"paragraph","text":[{"text":"Behavioural variables (5):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Occasions:","bold":true},{"text":" when buyers get the idea to buy, buy or use (festive gift packs)."}]},{"text":[{"text":"Benefits sought:","bold":true},{"text":" the benefit the buyer wants from the product (benefit segmentation)."}]},{"text":[{"text":"User status:","bold":true},{"text":" non-users, ex-users, potential users, first-time users, regular users."}]},{"text":[{"text":"Usage rate:","bold":true},{"text":" light, medium and heavy users."}]},{"text":[{"text":"Loyalty status:","bold":true},{"text":" how loyal buyers are to a brand."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Behavioural segmentation:","bold":true},{"text":" dividing buyers by their knowledge, attitudes, uses or responses to a product."}]},{"text":[{"text":"Psychographic segmentation:","bold":true},{"text":" dividing buyers by lifestyle, personality characteristics or values."}]},{"text":[{"text":"Production capacity of the selling firm is "},{"text":"not","bold":true},{"text":" a basis for segmentation; bases describe "},{"text":"buyers","bold":true},{"text":", not the seller."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Geographic:","bold":true},{"text":" a paint company sells different ranges in the rainy south and the dry, hot north of Nigeria because of climate."}]},{"text":[{"text":"Demographic:","bold":true},{"text":" the most popular basis because the variables are easy to measure and link closely to needs. A bank's savings account for customers aged 18 to 25 in tertiary institutions uses age and life stage. Income and population traits are demographic variables."}]},{"text":[{"text":"Psychographic:","bold":true},{"text":" a Lekki gym targeting young professionals who treat fitness, healthy eating and an active social life as central to how they live is using lifestyle. Some books place social class under demographic; most introductory marketing lists put it with lifestyle and personality."}]},{"text":[{"text":"Behavioural examples:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Usage rate:","bold":true},{"text":" a telecom operator such as MTN offering a special bundle to customers who use more than 20GB a month and a different plan to light users."}]},{"text":[{"text":"Occasion:","bold":true},{"text":" a biscuit company making gift packs sold only at Christmas and Sallah. The trigger is the festive occasion, so this is behavioural, not demographic by religion."}]},{"text":[{"text":"Benefits sought:","bold":true},{"text":" a toothpaste maker with one brand for whiter teeth, one for fresh breath and one for sensitive teeth."}]},{"text":[{"text":"Loyalty status:","bold":true},{"text":" an airline rewarding passengers who fly with it repeatedly and never switch."}]}]}]},{"text":[{"text":"Trap:","bold":true},{"text":" family size is "},{"text":"demographic","bold":true},{"text":", not behavioural. Region, city size and climate are geographic; lifestyle, personality and values are psychographic; usage rate, loyalty and benefits are behavioural."}]},{"text":[{"text":"Firms often combine bases (multiple segmentation), for example young (demographic), heavy-data (behavioural) users in Lagos (geographic)."}]},{"text":[{"text":"Business markets can be segmented by many of the same variables plus customer size, industry, purchasing approach and situational factors."}]}]}]},{"number":"6.3","title":"Requirements for effective segmentation","mustKnow":[{"type":"paragraph","text":[{"text":"A useful segment must be (5):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Measurable:","bold":true},{"text":" its size, purchasing power and profile can be estimated."}]},{"text":[{"text":"Accessible:","bold":true},{"text":" the firm can effectively reach and serv$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua125', 24, $study_guide$e it."}]},{"text":[{"text":"Substantial:","bold":true},{"text":" large or profitable enough to be worth a separate marketing programme."}]},{"text":[{"text":"Differentiable:","bold":true},{"text":" conceptually distinct, and responds differently to marketing mix elements than other segments."}]},{"text":[{"text":"Actionable:","bold":true},{"text":" the firm can design effective programmes to attract and serve it."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"A segment does "},{"text":"not","bold":true},{"text":" have to contain every consumer in the market; that would be mass marketing."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Match the definition to the word. Exams give the definition and ask for the term:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"\"Can be reached and served\" = "},{"text":"accessible","bold":true},{"text":", not measurable."}]},{"text":[{"text":"\"Size, purchasing power and profile can be estimated\" = "},{"text":"measurable","bold":true},{"text":"."}]},{"text":[{"text":"\"Large enough to be profitable\" = "},{"text":"substantial","bold":true},{"text":"."}]},{"text":[{"text":"\"Responds differently from other segments\" = "},{"text":"differentiable","bold":true},{"text":"."}]},{"text":[{"text":"\"Firm can design programmes to attract and serve it\" = "},{"text":"actionable","bold":true},{"text":"."}]}]}]},{"text":[{"text":"A group with clear needs but only a few dozen buyers, too small to cover a separate programme, fails "},{"text":"substantial","bold":true},{"text":"."}]},{"text":[{"text":"Left-handed people may be a distinct group, but they are hard to identify and reach, so they may fail "},{"text":"measurable","bold":true},{"text":" and "},{"text":"accessible","bold":true},{"text":"."}]},{"text":[{"text":"A small firm with resources for only one programme may find two attractive segments but can act on only one: the second fails "},{"text":"actionable","bold":true},{"text":" for that firm."}]}]}]},{"number":"6.4","title":"Targeting and positioning","mustKnow":[{"type":"paragraph","text":[{"text":"Steps in target marketing (STP), in order:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Segmentation:","bold":true},{"text":" divide the market into groups."}]},{"text":[{"text":"Targeting (market targeting):","bold":true},{"text":" evaluate the attractiveness of each segment and select one or more to enter."}]},{"text":[{"text":"Positioning:","bold":true},{"text":" arrange for the product to occupy a clear, distinctive and desirable place relative to competing products in the minds of target consumers."}]}]},{"type":"paragraph","text":[{"text":"Evaluating segments (3 factors):","bold":true},{"text":" (1) segment "},{"text":"size and growth","bold":true},{"text":"; (2) segment "},{"text":"structural attractiveness","bold":true},{"text":" (competitors, substitutes, power of buyers and suppliers); (3) company "},{"text":"objectives and resources","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"Targeting strategies:","bold":true}]},{"type":"table","header":[[{"text":"Strategy"}],[{"text":"What the firm does"}],[{"text":"Main advantage"}],[{"text":"Main drawback"}]],"rows":[[[{"text":"Undifferentiated (mass)"}],[{"text":"Ignores segment differences; one offer for the whole market"}],[{"text":"Lowest cost"}],[{"text":"Hard to satisfy everyone; open to focused rivals"}]],[[{"text":"Differentiated (segmented)"}],[{"text":"Targets several segments with a separate offer for each"}],[{"text":"Higher total sales and stronger position in each segment"}],[{"text":"Raises costs of product development, production and promotion"}]],[[{"text":"Concentrated (niche)"}],[{"text":"Goes after a large share of one small segment or niche; suits limited resources"}],[{"text":"Strong knowledge of customers and a strong niche position"}],[{"text":"Heavy dependence on one segment; a change there can hurt badly"}]],[[{"text":"Micromarketing"}],[{"text":"Tailors offers to local areas or individuals"}],[{"text":"Very close fit to needs"}],[{"text":"High cost; lower economies of scale"}]]]},{"type":"paragraph","text":[{"text":"Positioning:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Positioning statement:","bold":true},{"text":" to (target segment and need), our (brand) is (concept) that (point of difference)."}]},{"text":[{"text":"Firms differentiate through product, services, channels, people or image, and choose a "},{"text":"value proposition","bold":true},{"text":" (the full mix of benefits on which the brand is positioned)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A beverage company with a cheap sachet drink for low-income buyers, a premium bottled range for upper-income buyers and a sugar-free version for health-conscious buyers, each with its own advertising, uses "},{"text":"differentiated","bold":true},{"text":" marketing."}]},{"text":[{"text":"A small Lagos firm that serves only premium natural-hair products for one niche uses "},{"text":"concentrated","bold":true},{"text":" marketing."}]},{"text":[{"text":"A fast-food chain advertising itself as \"the fastest affordable meal for busy office workers in Lagos\" is "},{"text":"positioning","bold":true},{"text":": it names a target (busy office workers) and a point of difference (fast, affordable)."}]},{"text":[{"text":"Trap:","bold":true},{"text":" targeting is choosing segments; positioning is the place in the mind. The order is never positioning first."}]},{"text":[{"text":"Differentiated marketing does not \"ignore differences\" or \"serve one niche\"; it can raise total sales, but at higher cost."}]}]}]},{"number":"6.5","title":"Benefits, costs and implications for business","mustKnow":[{"type":"paragraph","text":[{"text":"Benefits of segmentation:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Bett$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua125', 25, $study_guide$er match of products and marketing mix to customers' needs."}]},{"text":[{"text":"More effective competition in chosen segments."}]},{"text":[{"text":"Spotting new market opportunities and unserved groups."}]},{"text":[{"text":"Efficient use of resources: spending is concentrated on the segments with the best returns."}]},{"text":[{"text":"Scope for different prices for groups with different price sensitivity."}]}]},{"type":"paragraph","text":[{"text":"Costs and limits:","bold":true},{"text":" more products, research and promotion raise costs; segments can be too small; segmentation does "},{"text":"not","bold":true},{"text":" always lower total marketing costs, guarantee no competitors, or remove the need for research."}]},{"type":"paragraph","text":[{"text":"Segment pricing rule:","bold":true},{"text":" if a firm can separate groups (and stop resale), it charges the "},{"text":"higher price","bold":true},{"text":" to the group whose demand is "},{"text":"less price elastic","bold":true},{"text":", and the lower price to the more elastic group."}]},{"type":"paragraph","text":[{"text":"Segment-size formulas:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Number of buyers in segment = total population x proportion with the trait x proportion who want the product."}]},{"text":[{"text":"Segment value (per period) = number of buyers x spending per buyer per period."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Managerial economics view:","bold":true},{"text":" segmentation is resource allocation. With a limited budget, a manager earns more by spending where the return per naira is highest than by spreading the budget equally over everyone."}]},{"text":[{"text":"Segment pricing example:","bold":true},{"text":" a cinema charges students less than working adults. Students have lower incomes and more alternatives, so their demand is more elastic; adults' demand is less elastic, so they pay more. Firms must be able to tell the groups apart (student ID) and prevent resale. Airlines, data plans by time of day and senior discounts follow the same logic."}]}]},{"type":"paragraph","text":[{"text":"Worked computation 1:","bold":true},{"text":" a campus food delivery start-up estimates 48,000 students; 35% order food online; each spends ₦2,500 a month."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Buyers = 48,000 x 0.35 = 16,800 students."}]},{"text":[{"text":"Monthly value = 16,800 x ₦2,500 = "},{"text":"₦42,000,000","bold":true},{"text":"."}]},{"text":[{"text":"Trap: 48,000 x ₦2,500 = ₦120,000,000 ignores the 35%."}]}]},{"type":"paragraph","text":[{"text":"Worked computation 2:","bold":true},{"text":" a town has 120,000 households; 40% earn above ₦300,000 a month; 25% of those want a home-cleaning service."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"High-income households = 120,000 x 0.40 = 48,000."}]},{"text":[{"text":"Target segment = 48,000 x 0.25 = "},{"text":"12,000 households","bold":true},{"text":"."}]},{"text":[{"text":"Trap: 48,000 is the income group only; 30,000 wrongly applies 25% to all households."}]},{"text":[{"text":"Implications for managers:","bold":true},{"text":" choose bases that link to buying behaviour; check all 5 requirements before committing money; pick a targeting strategy that fits resources (concentrated for small firms, differentiated for large ones such as Nestlé Nigeria or Dangote); position clearly; review segments as incomes, tastes and technology change."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Segmentation = dividing a market into distinct groups with different needs; a segment responds similarly to a set of marketing efforts. Wendell Smith introduced the concept (1956)."}]},{"text":[{"text":"4 bases: geographic, demographic, psychographic, behavioural."}]},{"text":[{"text":"Demographic: age, gender, income, family size; psychographic: lifestyle, personality, values."}]},{"text":[{"text":"Behavioural: occasions, benefits sought, user status, usage rate, loyalty status."}]},{"text":[{"text":"5 requirements: measurable, accessible, substantial, differentiable, actionable."}]},{"text":[{"text":"STP order: segmentation, targeting, positioning."}]},{"text":[{"text":"Undifferentiated (one offer), differentiated (many offers, higher cost), concentrated (one niche, high dependence), micromarketing."}]},{"text":[{"text":"Positioning = a clear, distinctive, desirable place in target consumers' minds."}]},{"text":[{"text":"Charge the higher price to the less price-elastic segment."}]},{"text":[{"text":"Segment value = population x proportions x spending per buyer."}]}]}],"theory":{"itemId":"676cac5a-37f5-5f0d-a8da-ac1420773b8b","question":[{"type":"paragraph","text":[{"text":"A snack firm with a small budget compares two campus segments. Segment A: 30,000 students, 20% interested, each spending ₦4,000 a month. Segment B: 8,000 staff, 50% interested, each spending ₦5,000 a month. Find each segment's monthly value and name the targeting strategy if the firm serves only the better one."}]}]},"practice":[{"topic":"Market Segmentation","named":false}]}},{"kind":"note","itemId":"7de820f3-a718-570b-ab1d-a3141decf828","sourceKey":"guide-topic:7","position":7,"payload":{"title":"Theory of Firms","body":"What a firm is; the traditional, managerial and behavioural theories of the firm and their objectives; the types of firms (sole proprietorship, partnership, private and public limited liability companies, public enterprises) with their features, advantages and disadvantages; how companies are formed and financed in Nigeria (CAC, CAMA 2020); privatisation and commercialisation.","noteType":"guide_topic","number":7,"mustKnow":[{"text":"What a firm is; the traditional, managerial and behavioural theories of the firm and their objectives; the types of firms (sole proprietorship, partnership, private and public limited liability companies, public enterprises) wit$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua125', 26, $study_guide$h their features, advantages and disadvantages; how companies are formed and financed in Nigeria (CAC, CAMA 2020); privatisation and commercialisation."}],"lessons":[{"number":"7.1","title":"What a firm is and theories of the firm","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Firm:","bold":true},{"text":" a business organisation that brings together the factors of production (land, labour, capital, entrepreneurship) to produce goods or services for sale, usually to make a profit. A group of firms producing the same product is an "},{"text":"industry","bold":true},{"text":"; a single factory or production unit is a "},{"text":"plant","bold":true},{"text":"."}]},{"text":[{"text":"Why firms exist (Ronald Coase, 1937):","bold":true},{"text":" using the market for every transaction has costs (searching, bargaining, contracting). A firm exists because organising some activities inside it is cheaper than buying them through the market ("},{"text":"transaction-cost theory","bold":true},{"text":")."}]}]},{"type":"paragraph","text":[{"text":"Theories (objectives) of the firm:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Traditional (neoclassical) theory: profit maximisation.","bold":true},{"text":" The firm aims to "},{"text":"maximise profit by producing where marginal revenue equals marginal cost (MR = MC)","bold":true},{"text":". Assumptions:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"the firm is "},{"text":"managed by its owner-entrepreneur","bold":true},{"text":";"}]},{"text":[{"text":"it has a "},{"text":"single goal of maximum profit","bold":true},{"text":";"}]},{"text":[{"text":"it has "},{"text":"full knowledge of its costs and revenues","bold":true},{"text":";"}]},{"text":[{"text":"it acts rationally."}]}]}]},{"text":[{"text":"Managerial theories:","bold":true},{"text":" arose because in large modern companies "},{"text":"ownership by shareholders is separated from control by professional managers","bold":true},{"text":" (Berle and Means, 1932). Managers pursue their own goals, subject to keeping shareholders satisfied."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Sales revenue maximisation (William Baumol):","bold":true},{"text":" managers make "},{"text":"total sales revenue as large as possible, provided profit does not fall below the minimum level that keeps shareholders satisfied","bold":true},{"text":"."}]},{"text":[{"text":"Managerial utility maximisation (Oliver Williamson):","bold":true},{"text":" managers maximise their own satisfaction by spending on "},{"text":"extra staff, perks (luxury cars, big offices) and discretionary investment","bold":true},{"text":", as long as profits stay acceptable to shareholders."}]},{"text":[{"text":"Growth maximisation (Robin Marris):","bold":true},{"text":" managers aim at the "},{"text":"fastest possible expansion","bold":true},{"text":" of the firm, "},{"text":"subject to keeping the firm safe from takeover","bold":true},{"text":" (job security)."}]}]}]},{"text":[{"text":"Behavioural theory (Cyert and March; Herbert Simon):","bold":true},{"text":" the firm is "},{"text":"a coalition of groups (managers, workers, shareholders, customers, suppliers) with different and often conflicting goals","bold":true},{"text":". Because information is limited (bounded rationality), it "},{"text":"satisfices","bold":true},{"text":": aims at "},{"text":"satisfactory levels of performance rather than the maximum possible","bold":true},{"text":"."}]},{"text":[{"text":"Value (wealth) maximisation:","bold":true},{"text":" the firm aims to maximise the present value of expected future profits, i.e. the owners' wealth (share price)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: \"a coalition of groups that settles for satisfactory results\" is the "},{"text":"behavioural","bold":true},{"text":" view, so it is "},{"text":"NOT","bold":true},{"text":" an assumption of the traditional profit-maximisation theory."}]},{"text":[{"text":"Match the clue to the theory: \"as large as possible ... minimum profit\" = "},{"text":"Baumol (sales)","bold":true},{"text":"; \"staff, official cars, offices, status\" = "},{"text":"Williamson (managerial utility)","bold":true},{"text":"; \"fastest expansion ... safe from takeover\" = "},{"text":"Marris (growth)","bold":true},{"text":"; \"satisfactory, not maximum\" and \"coalition\" = "},{"text":"behavioural (satisficing)","bold":true},{"text":"; \"MR = MC\" and \"owner-entrepreneur\" = "},{"text":"traditional","bold":true},{"text":"."}]},{"text":[{"text":"Why Baumol? Managers' pay, prestige and bank goodwill tend to rise with the size of sales, not profit. A Plc such as MTN Nigeria is run by hired executives, not by the thousands of shareholders who own it: the separation that managerial theories describe."}]},{"text":[{"text":"The "},{"text":"principal-agent problem","bold":true},{"text":": shareholders (principals) hire managers (agents) who may not act in the owners' interest. Boards, audits and share-based pay are ways to align them."}]}]}]},{"number":"7.2","title":"Sole proprietorship","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Sole proprietorship:","bold":true},{"text":" a business "},{"text":"owned, financed and controlled by one person","bold":true},{"text":", who "},{"text":"takes all the profit and bears all the risk","bold":true},{"text":". It is the "},{"text":"most common form of business in Nigeria","bold":true},{"text":", mainly because it is "},{"text":"easy and cheap to set up, with few legal formalities","bold":true},{"text":"."}]},{"text":[{"text":"Main source of capital:","bold":true},{"text":" "},{"text":"personal savings and loans from family and friends","bold":true},{"text":"; also small loans from banks, microfinance banks, cooperatives and esusu/ajo contribution groups."}]}]},{"type":"paragraph","text":[{"text":"Features:","bol$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua125', 27, $study_guide$d":true},{"text":" one owner; owner makes all decisions; "},{"text":"unlimited liability","bold":true},{"text":"; no separate legal personality (the owner and the business are the same in law); few legal formalities (only registration of a business name with the "},{"text":"Corporate Affairs Commission (CAC)","bold":true},{"text":" if it trades under a name other than the owner's)."}]},{"type":"paragraph","text":[{"text":"Advantages:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Easy and cheap to set up, with few legal formalities.","bold":true}]},{"text":[{"text":"Quick decision-making","bold":true},{"text":" because the owner does not need to consult anyone."}]},{"text":[{"text":"The owner keeps all the profits.","bold":true}]},{"text":[{"text":"Close personal contact with customers and workers."}]},{"text":[{"text":"Privacy: accounts need not be published."}]},{"text":[{"text":"Flexibility: easy to change line of business."}]}]},{"type":"paragraph","text":[{"text":"Disadvantages:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Unlimited liability:","bold":true},{"text":" the owner's personal property can be taken to pay business debts."}]},{"text":[{"text":"Limited capital","bold":true},{"text":" for expansion."}]},{"text":[{"text":"Lack of continuity:","bold":true},{"text":" the business may die or close with the owner."}]},{"text":[{"text":"Heavy workload; the owner may lack some skills."}]},{"text":[{"text":"All losses are borne by one person."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Mama Bisi runs a provision shop alone. It fails owing suppliers ₦2 million, more than the shop's assets. Creditors take her "},{"text":"personal car","bold":true},{"text":": this shows "},{"text":"unlimited liability","bold":true},{"text":"."}]},{"text":[{"text":"Trap: \"the owner keeps all the profits\" is an "},{"text":"advantage","bold":true},{"text":", so it is NOT a disadvantage. \"Limited liability\", \"easy access to large capital\" and \"continuity after death\" are NOT advantages of a sole proprietorship."}]},{"text":[{"text":"Examples: barbing salons, POS agents, provision shops, tailors, roadside food sellers."}]}]}]},{"number":"7.3","title":"Partnership","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Partnership:","bold":true},{"text":" the relationship between persons "},{"text":"carrying on a business in common with a view of profit","bold":true},{"text":", who share capital, management and profits. In Nigeria, an ordinary partnership generally has "},{"text":"2 to 20 partners","bold":true},{"text":"; a larger association must register as a company (CAMA 2020 exempts partnerships of lawyers or of accountants from the 20 limit)."}]},{"text":[{"text":"Deed of partnership:","bold":true},{"text":" the "},{"text":"written agreement that sets out the rights, duties and profit-sharing arrangements of the partners","bold":true},{"text":" (capital contributed, profit and loss ratio, salaries, interest on capital, admission, retirement and dissolution)."}]}]},{"type":"paragraph","text":[{"text":"Types of partners:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Active (managing, general) partner:","bold":true},{"text":" contributes capital and takes part in running the business."}]},{"text":[{"text":"Sleeping (dormant) partner:","bold":true},{"text":" contributes capital and shares profit but "},{"text":"takes no part in running the business","bold":true},{"text":"."}]},{"text":[{"text":"Nominal partner:","bold":true},{"text":" "},{"text":"allows his name to be used","bold":true},{"text":" to give the firm credibility, but "},{"text":"contributes no capital and takes no part in management","bold":true},{"text":"."}]},{"text":[{"text":"Limited partner:","bold":true},{"text":" "},{"text":"liable only up to the capital contributed and does not take part in managing the business","bold":true},{"text":". A limited partnership must have at least one general partner with unlimited liability."}]},{"text":[{"text":"Minor partner:","bold":true},{"text":" a minor (below the age of majority) admitted to share in the benefits."}]}]},{"type":"paragraph","text":[{"text":"Types of partnership:","bold":true},{"text":" ordinary (general) partnership; limited partnership; limited liability partnership (LLP), which CAMA 2020 allows to be registered with the CAC."}]},{"type":"paragraph","text":[{"text":"Liability:","bold":true},{"text":" in an "},{"text":"ordinary (general) partnership","bold":true},{"text":", liability is "},{"text":"unlimited","bold":true},{"text":", so partners' private assets can be used to pay the firm's debts."}]},{"type":"paragraph","text":[{"text":"Advantages (over a sole proprietorship):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"More capital","bold":true},{"text":" can be raised from several owners."}]},{"text":[{"text":"Partners share skills and can specialise.","bold":true}]},{"text":[{"text":"Losses and responsibilities are shared.","bold":true}]},{"text":[{"text":"Better decisions from pooled ideas; easy to form."}]}]},{"type":"paragraph","text":[{"text":"Disadvantages:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Unlimited liability","bold":true},{"text":" (for general partners)."}]},{"text":[{"text":"Each partner can be bound by the actions of the other partners","bold":true},{"text":" (mutual agency)."}]},{"text":[{"text":"Lack of continuity:","bold":true},{"text":" death, retirement or bankruptcy of a partner generally "},{"text":"dissolves","bold":true},{"text":" the partnership."}]},{"text":[{"text":"Disagreements between partners; slower decisions."}]},{"text":[{"text":"Capital still limited compared with a company; shares cannot be transferred without the others' consent."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"tex$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua125', 28, $study_guide$t":[{"text":"Chidi puts ₦5 million into a partnership but takes no part in running it: he is a "},{"text":"sleeping (dormant) partner","bold":true},{"text":". A famous retired judge lending only his name to a law firm, with no capital, is a "},{"text":"nominal partner","bold":true},{"text":"."}]},{"text":[{"text":"Trap: \"each partner can be bound by the actions of the other partners\" is a "},{"text":"disadvantage","bold":true},{"text":", NOT an advantage."}]},{"text":[{"text":"If one of three lawyers in a partnership dies and there is no continuation clause, the partnership is generally "},{"text":"dissolved","bold":true},{"text":", though the remaining partners may form a new one. It does not have perpetual succession."}]},{"text":[{"text":"Partnerships are common among professionals: law, accounting and medical practices."}]}]}]},{"number":"7.4","title":"Limited liability companies","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Limited liability:","bold":true},{"text":" shareholders can lose "},{"text":"no more than the amount they paid (or agreed to pay) for their shares","bold":true},{"text":". It is a key benefit of "},{"text":"limited liability companies","bold":true},{"text":", both "},{"text":"private (Ltd) and public (Plc)","bold":true},{"text":", not of sole proprietorships or ordinary partnerships."}]},{"text":[{"text":"Separate legal entity:","bold":true},{"text":" the company "},{"text":"can own property, sue and be sued in its own name, apart from its owners","bold":true},{"text":"."}]},{"text":[{"text":"Perpetual succession:","bold":true},{"text":" the company "},{"text":"continues in existence even when its shareholders die or sell their shares","bold":true},{"text":"."}]},{"text":[{"text":"Registration:","bold":true},{"text":" companies are registered by the "},{"text":"Corporate Affairs Commission (CAC)","bold":true},{"text":", which issues the "},{"text":"certificate of incorporation","bold":true},{"text":", under the "},{"text":"Companies and Allied Matters Act (CAMA) 2020","bold":true},{"text":"."}]},{"text":[{"text":"Memorandum of association:","bold":true},{"text":" sets out the company's "},{"text":"name, objects and relationship with the outside world","bold":true},{"text":" (also its liability and share capital)."}]},{"text":[{"text":"Articles of association:","bold":true},{"text":" the "},{"text":"internal rules","bold":true},{"text":" for running the company's meetings and management."}]}]},{"type":"table","header":[[{"text":"Feature"}],[{"text":"Private limited company (Ltd)"}],[{"text":"Public limited company (Plc)"}]],"rows":[[[{"text":"Sale of shares"}],[{"text":"Cannot","bold":true},{"text":" invite the public; "},{"text":"restricts transfer","bold":true},{"text":" of shares"}],[{"text":"Can invite the general public","bold":true},{"text":" to buy shares; shares freely transferable (may be listed on the Nigerian Exchange)"}]],[[{"text":"Members (CAMA 2020)"}],[{"text":"at least 1, at most 50 (employees not counted)"}],[{"text":"at least 2, no maximum"}]],[[{"text":"Name ends in"}],[{"text":"\"Limited\" / \"Ltd\""}],[{"text":"\"Plc\""}]],[[{"text":"Disclosure"}],[{"text":"less"}],[{"text":"must publish much financial information","bold":true}]],[[{"text":"Liability"}],[{"text":"limited"}],[{"text":"limited"}]],[[{"text":"Legal personality"}],[{"text":"separate"}],[{"text":"separate"}]]]},{"type":"paragraph","text":[{"text":"Advantages of a Plc:","bold":true},{"text":" raises "},{"text":"very large amounts of capital from the public","bold":true},{"text":"; limited liability; perpetual succession; shares are easy to sell; easier borrowing; can hire professional managers."}]},{"type":"paragraph","text":[{"text":"Disadvantages of a Plc:","bold":true},{"text":" "},{"text":"formation is costly with many legal requirements","bold":true},{"text":"; "},{"text":"must disclose much of its financial information to the public","bold":true},{"text":"; "},{"text":"ownership is separated from control","bold":true},{"text":"; slow, bureaucratic decisions; risk of takeover; heavy regulation."}]},{"type":"paragraph","text":[{"text":"Advantages of an Ltd:","bold":true},{"text":" limited liability; separate legal personality; continuity; more privacy than a Plc; owners keep control. "},{"text":"Disadvantages:","bold":true},{"text":" cannot raise capital from the public; shares not freely transferable; more formalities than a sole proprietorship or partnership."}]},{"type":"paragraph","text":[{"text":"Company finance:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Ordinary shares:","bold":true},{"text":" holders are "},{"text":"owners","bold":true},{"text":" who receive "},{"text":"variable dividends","bold":true},{"text":", have "},{"text":"voting rights","bold":true},{"text":", and are paid "},{"text":"last","bold":true},{"text":" when a company is wound up."}]},{"text":[{"text":"Preference shares:","bold":true},{"text":" "},{"text":"fixed rate of dividend","bold":true},{"text":", paid "},{"text":"before","bold":true},{"text":" ordinary shareholders, usually "},{"text":"limited voting rights","bold":true},{"text":"."}]},{"text":[{"text":"Debentures:","bold":true},{"text":" loans to the company; holders are "},{"text":"creditors","bold":true},{"text":" who receive "},{"text":"fixed interest","bold":true},{"text":" whether or not there is profit, and are paid before shareholders."}]},{"text":[{"text":"Internal finance:","bold":true},{"text":" "},{"text":"retained earnings (ploughed-back profits)","bold":true},{"text":", sale of assets. "},{"text":"External finance:","bold":true},{"text":" new shares, debentures, bank loans and overdrafts."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Ade owns 10,000 fully paid shares in a company that goes into liquidation owing large debts. The most he can lose is "},{"text":"the amount he paid for his shares","bold":true},{"text":"; his house and $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua125', 29, $study_guide$car are safe."}]},{"text":[{"text":"Trap: \"shareholders of a Plc have unlimited liability\" is false, so it is "},{"text":"NOT","bold":true},{"text":" a disadvantage of a Plc. Both Ltd and Plc give limited liability; that is "},{"text":"not","bold":true},{"text":" the difference between them. The key difference is that "},{"text":"a Plc can invite the public to buy its shares, while an Ltd cannot","bold":true},{"text":"."}]},{"text":[{"text":"Examples of Plcs: Dangote Cement Plc, MTN Nigeria Communications Plc, Nestlé Nigeria Plc. Many family-owned businesses and start-ups register as Ltd."}]},{"text":[{"text":"CAMA 2020 also recognises companies "},{"text":"limited by guarantee","bold":true},{"text":" (often non-profit, such as associations) and "},{"text":"unlimited companies","bold":true},{"text":"."}]},{"text":[{"text":"Do not confuse the CAC (registers companies) with FIRS (collects federal taxes), the CBN (central bank) or the NPA (ports)."}]}]}]},{"number":"7.5","title":"Public enterprises","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Public corporation (public enterprise):","bold":true},{"text":" a business organisation "},{"text":"established by an Act of the legislature, owned and financed by government, and run by a board appointed by government","bold":true},{"text":" to provide essential services."}]},{"text":[{"text":"Main source of capital:","bold":true},{"text":" "},{"text":"government funding through budget allocations, grants and loans","bold":true},{"text":" (plus revenue from its services)."}]}]},{"type":"paragraph","text":[{"text":"Features:","bold":true},{"text":" created by statute; government ownership and control; separate legal entity; board appointed by government (minister); service motive rather than profit motive; accountable to the public through the legislature; profits go back to government, losses usually covered by subsidy."}]},{"type":"paragraph","text":[{"text":"Reasons governments set them up (advantages):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"To provide essential services that private firms may not provide adequately or at affordable prices","bold":true},{"text":" (water, power, rail)."}]},{"text":[{"text":"To control strategic industries (oil, defence, ports)."}]},{"text":[{"text":"To prevent exploitation by private monopolies."}]},{"text":[{"text":"To undertake projects too large or risky for private investors."}]},{"text":[{"text":"To create employment and promote balanced regional development."}]}]},{"type":"paragraph","text":[{"text":"Problems (disadvantages) in Nigeria:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Political interference","bold":true},{"text":" in management and appointments."}]},{"text":[{"text":"Inefficiency and dependence on government subsidies.","bold":true}]},{"text":[{"text":"Bureaucracy and slow decision-making.","bold":true}]},{"text":[{"text":"Corruption, overstaffing and poor service."}]},{"text":[{"text":"Lack of profit motive and accountability."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Privatisation:","bold":true},{"text":" "},{"text":"transfers ownership","bold":true},{"text":" (fully or partly) of a public enterprise "},{"text":"to private investors","bold":true},{"text":"."}]},{"text":[{"text":"Commercialisation:","bold":true},{"text":" "},{"text":"keeps government ownership","bold":true},{"text":" but requires the enterprise to "},{"text":"run on profit-oriented (commercial) lines","bold":true},{"text":", charging economic prices and funding itself."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Examples: Nigerian Railway Corporation (NRC), Nigerian Ports Authority (NPA), Nigerian Postal Service (NIPOST). The power-generation and distribution companies of the former PHCN were privatised in 2013. NNPC was converted into NNPC Limited in 2022 under the Petroleum Industry Act 2021 and run on commercial lines."}]},{"text":[{"text":"Privatisation and commercialisation in Nigeria are handled by the "},{"text":"Bureau of Public Enterprises (BPE)","bold":true},{"text":" under the Public Enterprises (Privatisation and Commercialisation) Act 1999."}]},{"text":[{"text":"Trap: \"excessive pressure from private shareholders to pay dividends\" is "},{"text":"NOT","bold":true},{"text":" a problem of public enterprises: they have no private shareholders. \"To maximise dividends to private shareholders\" is not a reason for setting them up."}]},{"text":[{"text":"Trap: exams reverse the two terms. "},{"text":"Privatisation = ownership changes; commercialisation = ownership stays with government, behaviour becomes commercial.","bold":true}]}]},{"type":"paragraph","text":[{"text":"Summary comparison:","bold":true}]},{"type":"table","header":[[{"text":"Form"}],[{"text":"Owners"}],[{"text":"Liability"}],[{"text":"Legal personality"}],[{"text":"Continuity"}],[{"text":"Main capital source"}]],"rows":[[[{"text":"Sole proprietorship"}],[{"text":"1"}],[{"text":"unlimited"}],[{"text":"none"}],[{"text":"ends with owner"}],[{"text":"personal savings, family and friends"}]],[[{"text":"Ordinary partnership"}],[{"text":"2 to 20"}],[{"text":"unlimited"}],[{"text":"none"}],[{"text":"dissolves on death of a partner"}],[{"text":"partners' contributions"}]],[[{"text":"Private company (Ltd)"}],[{"text":"1 to 50"}],[{"text":"limited"}],[{"text":"separate"}],[{"text":"perpetual succession"}],[{"text":"private shares, retained earnings, loans"}]],[[{"text":"Public company (Plc)"}],[{"text":"2 or more"}],[{"text":"limited"}],[{"text":"separate"}],[{"text":"perpetual succession"}],[{"text":"public share issues, debentures"}]],[[{"text":"Public enterprise"}],[{"text":"government"}],[{"text":"not applicable (state-owned)"}],[{"text":"separate (statutory)"}],[{"text":"as long as the Act stands"}],[{"text":"government budget, grants, loans"}]]]}]}],"recap":[{"type":"list","ordered":false,"items":[$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua125', 30, $study_guide${"text":[{"text":"A firm combines factors of production to produce for sale; Coase: firms exist to save transaction costs."}]},{"text":[{"text":"Traditional theory: owner-entrepreneur, single goal, full knowledge, profit maximised at MR = MC."}]},{"text":[{"text":"Managerial theories come from separation of ownership and control: Baumol (sales revenue with minimum profit), Williamson (managerial utility: staff, perks), Marris (growth, safe from takeover)."}]},{"text":[{"text":"Behavioural theory (Cyert and March, Simon): coalition of groups; satisficing."}]},{"text":[{"text":"Sole proprietor: one owner, all profit, all risk, unlimited liability, quick decisions, limited capital, no continuity."}]},{"text":[{"text":"Partnership: 2 to 20 partners, deed of partnership; sleeping, nominal, limited partners; unlimited liability and mutual agency."}]},{"text":[{"text":"Ltd and Plc both give limited liability, separate legal entity and perpetual succession; only a Plc can sell shares to the public."}]},{"text":[{"text":"CAC registers companies under CAMA 2020; memorandum = external, articles = internal."}]},{"text":[{"text":"Ordinary shares: owners, variable dividend; preference: fixed dividend, paid first; debentures: creditors, fixed interest; retained earnings = internal finance."}]},{"text":[{"text":"Public enterprise: statute, government-owned and financed, essential services; privatisation transfers ownership, commercialisation keeps it."}]}]}],"theory":{"itemId":"060f6630-377b-5ee1-a865-be44efa268f4","question":[{"type":"paragraph","text":[{"text":"State three differences between a private limited company and a public limited company, and one feature they share."}]}]},"practice":[{"topic":"Theory of Firms","named":false}]}},{"kind":"note","itemId":"9c3a640f-97cd-5bf2-8254-d03b9293cf9f","sourceKey":"guide-topic:8","position":8,"payload":{"title":"Market Structure: Types of Market and Competition Analysis","body":"The meaning and 7 types of market structure; revenue, profit and efficiency tools and the MR = MC rule; perfect competition, monopoly (with price discrimination), monopolistic competition, duopoly, oligopoly (kinked demand, collusion, cartels), monopsony and duopsony; how each sets price and output in the short and long run; the computations.","noteType":"guide_topic","number":8,"mustKnow":[{"text":"The meaning and 7 types of market structure; revenue, profit and efficiency tools and the MR = MC rule; perfect competition, monopoly (with price discrimination), monopolistic competition, duopoly, oligopoly (kinked demand, collusion, cartels), monopsony and duopsony; how each sets price and output in the short and long run; the computations."}],"lessons":[{"number":"8.1","title":"Market structure and the core tools","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Market structure:","bold":true},{"text":" the operations of different industries and their classification in terms of the "},{"text":"degree and nature of competition","bold":true},{"text":" that differentiate them."}]},{"text":[{"text":"Industry:","bold":true},{"text":" a group of firms producing similar or identical products. "},{"text":"Firm:","bold":true},{"text":" a business unit that owns and runs one or more plants. "},{"text":"Plant:","bold":true},{"text":" a single production unit (a factory)."}]},{"text":[{"text":"7 types of market structure:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Perfect competition"}]},{"text":[{"text":"Monopoly"}]},{"text":[{"text":"Duopoly"}]},{"text":[{"text":"Oligopoly"}]},{"text":[{"text":"Monopolistic competition"}]},{"text":[{"text":"Monopsony (one buyer)"}]},{"text":[{"text":"Duopsony (two buyers)"}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"The most important basis of classification is "},{"text":"the number of firms and the degree of product differentiation","bold":true},{"text":". Ease of entry and power over price follow from these."}]},{"text":[{"text":"Revenue formulas:","bold":true},{"text":" TR = P × Q. AR = TR ÷ Q = P. MR = change in TR ÷ change in Q (the extra revenue from one more unit)."}]},{"text":[{"text":"Profit:","bold":true},{"text":" total profit = TR − TC = (P − ATC) × Q."}]},{"text":[{"text":"Normal profit:","bold":true},{"text":" the minimum profit needed to keep a firm in its present industry, earned when total revenue just covers total cost "},{"text":"including opportunity cost","bold":true},{"text":" (zero economic profit). "},{"text":"Supernormal (economic) profit:","bold":true},{"text":" any profit above normal profit."}]},{"text":[{"text":"The profit-maximising rule (all market structures):","bold":true},{"text":" produce where "},{"text":"MR = MC","bold":true},{"text":" (with MC rising). In a table: keep producing each extra unit while MR is at least MC; stop before the first unit whose MC exceeds its MR."}]},{"text":[{"text":"Productive efficiency:","bold":true},{"text":" producing at the "},{"text":"lowest possible average cost","bold":true},{"text":" (minimum ATC). "},{"text":"Allocative efficiency:","bold":true},{"text":" "},{"text":"P = MC","bold":true},{"text":" (price equals the cost of the last unit, so society gets the right amount)."}]},{"text":[{"text":"Barriers to entry:","bold":true},{"text":" anything that stops new firms entering: economies of scale, patents, government licences, ownership of a strategic raw material, access to technology others cannot get, huge capital needs."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"\"Communism\" is an economic "},{"text":"system","bold":true},{"text":", not a market structure. So are capitalism and the mixed economy. Market structures describe competition "},{"text":"inside an industry","bold":true},{"text":"."}]},{"text":[{"text":"Minimum efficient scale (MES):","bold":true},{"text":" the smallest output at which long-run average cost reaches its lowest. If MES is very large relative to$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua125', 31, $study_guide$ total market demand, the market can hold "},{"text":"only one or a few firms","bold":true},{"text":" (monopoly or oligopoly). If MES is small, many small firms survive."}]},{"text":[{"text":"Worked MR from a change in TR:","bold":true},{"text":" TR rises from ₦36,000 to ₦40,200 when sales rise from 150 to 165 units. MR = (40,200 − 36,000) ÷ (165 − 150) = 4,200 ÷ 15 = "},{"text":"₦280 per unit","bold":true},{"text":". Trap: ₦4,200 is the change in TR, not MR."}]},{"text":[{"text":"Trap: profit is maximised at MR = MC, "},{"text":"not","bold":true},{"text":" where TR is greatest and "},{"text":"not","bold":true},{"text":" where ATC is lowest."}]}]}]},{"number":"8.2","title":"Perfect competition","mustKnow":[{"type":"paragraph","text":[{"text":"Features:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"A "},{"text":"complete absence of rivalry","bold":true},{"text":" among firms; all sellers (and buyers) have "},{"text":"perfect knowledge","bold":true},{"text":" of the market."}]},{"text":[{"text":"A "},{"text":"large number of firms","bold":true},{"text":" and a "},{"text":"large number of buyers","bold":true},{"text":"."}]},{"text":[{"text":"A single firm cannot alter the market price; likewise one buyer cannot influence it."}]},{"text":[{"text":"Price is set solely by the "},{"text":"price mechanism","bold":true},{"text":" (market demand and supply), so firms are "},{"text":"price takers","bold":true},{"text":"."}]},{"text":[{"text":"The exit of a firm has no influence on price."}]},{"text":[{"text":"Products are "},{"text":"homogeneous","bold":true},{"text":" (identical): no room for product differentiation, so each firm's product has many "},{"text":"perfect substitutes","bold":true},{"text":"."}]},{"text":[{"text":"No barriers","bold":true},{"text":" to entry or exit (free entry and exit), and no government regulation."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Demand facing one firm:","bold":true},{"text":" "},{"text":"perfectly elastic (horizontal)","bold":true},{"text":" at the market price. So "},{"text":"P = AR = MR","bold":true},{"text":"."}]},{"text":[{"text":"Equilibrium:","bold":true},{"text":" profit is maximised where "},{"text":"MR = MC","bold":true},{"text":", which here means "},{"text":"P = MC","bold":true},{"text":"."}]},{"text":[{"text":"Short run:","bold":true},{"text":" the firm may earn supernormal profit, normal profit or a loss."}]},{"text":[{"text":"Shut-down rule (short run):","bold":true},{"text":" keep producing if P ≥ AVC (revenue covers variable cost and pays part of fixed cost); "},{"text":"shut down if P < AVC","bold":true},{"text":". When shut down, the loss = total fixed cost."}]},{"text":[{"text":"Short-run supply curve:","bold":true},{"text":" the part of the MC curve lying "},{"text":"above the minimum point of the AVC curve","bold":true},{"text":"."}]},{"text":[{"text":"Long run:","bold":true},{"text":" supernormal profit attracts "},{"text":"new firms","bold":true},{"text":", market supply rises and price falls until only "},{"text":"normal profit","bold":true},{"text":" is earned. Losses make firms "},{"text":"exit","bold":true},{"text":", market supply falls and price rises. Entry and exit stop when firms make "},{"text":"zero economic profit","bold":true},{"text":". Long-run equilibrium: "},{"text":"P = MC = minimum ATC","bold":true},{"text":" (both productively and allocatively efficient)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A firm's only real choices: produce more, produce less, or leave the industry. It "},{"text":"cannot","bold":true},{"text":" raise its price above the market price: it would sell nothing."}]},{"text":[{"text":"Perfect competition is a "},{"text":"theoretical model","bold":true},{"text":"; its strict assumptions rarely all hold. The nearest real example is "},{"text":"farming of a staple crop","bold":true},{"text":" (for example many tomato or maize farmers selling identical produce at the market price). Diamonds, soft drinks (Coca-Cola, Pepsi, Bigi) and branded trainers are "},{"text":"not","bold":true},{"text":" close."}]},{"text":[{"text":"Producing where P is not equal to MC:","bold":true},{"text":" if P > MC, producing more adds more to revenue than to cost, so the firm "},{"text":"raises profit by producing more","bold":true},{"text":". If P < MC, it should produce less."}]},{"text":[{"text":"When firms exit, the market "},{"text":"quantity supplied falls","bold":true},{"text":" (supply shifts left), so price "},{"text":"rises","bold":true},{"text":"; exit does "},{"text":"not","bold":true},{"text":" drive prices down."}]}]},{"type":"paragraph","text":[{"text":"Worked examples (check every step):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"TR and MR.","bold":true},{"text":" A garri seller in a competitive market sells 400 buckets at ₦1,500. TR = 1,500 × 400 = "},{"text":"₦600,000","bold":true},{"text":". MR = AR = P = "},{"text":"₦1,500","bold":true},{"text":" (every extra bucket adds exactly the price)."}]},{"text":[{"text":"Output from a MC table.","bold":true},{"text":" Price ₦1,500. MC of units 1 to 6: ₦900, ₦1,100, ₦1,300, ₦1,450, ₦1,600, ₦1,800. Units 1 to 4 each have MC below ₦1,500 (the 4th adds ₦1,500 − ₦1,450 = ₦50 profit). The 5th costs ₦1,600 > ₦1,500, so it loses ₦100. Produce "},{"text":"4 units","bold":true},{"text":"."}]},{"text":[{"text":"Profit.","bold":true},{"text":" Q = 2,000 where MR = MC, P = ₦600, ATC = ₦520. Profit = (600 − 520) × 2,000 = "},{"text":"₦160,000","bold":true},{"text":" (supernormal, since P > ATC)."}]},{"text":[{"text":"Loss but keep producing.","bold":true},{"text":" P = ₦600, ATC = ₦650, AVC = ₦560, Q = 2,000. Loss = (600 − 650) × 2,000 = "},{"text":"−₦100,000","bold":true},{"text":". Since P (₦600) > AVC (₦560), keep producing. If it shut down it would lose all fixed cost: AFC = 650 − 560 = ₦90, so FC = 90 × 2,000 = ₦180,000. Producing loses$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua125', 32, $study_guide$ ₦80,000 less."}]},{"text":[{"text":"Shut down.","bold":true},{"text":" Same costs but P = ₦500 < AVC ₦560. Producing loss = (500 − 650) × 2,000 = −₦300,000; shutting down loses only FC ₦180,000. "},{"text":"Shut down","bold":true},{"text":": loss is ₦120,000 smaller."}]},{"text":[{"text":"ATC from TC.","bold":true},{"text":" TC = ₦3,300,000 for 1,500 units. ATC = 3,300,000 ÷ 1,500 = "},{"text":"₦2,200","bold":true},{"text":". At P = ₦2,000 (below ATC) the firm makes a loss of (2,000 − 2,200) × 1,500 = −₦300,000. If P were above ATC it would earn supernormal profit."}]}]}]},{"number":"8.3","title":"Monopoly and price discrimination","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Monopoly:","bold":true},{"text":" a market with a "},{"text":"single firm or seller","bold":true},{"text":"; the firm "},{"text":"is","bold":true},{"text":" the industry and sells to numerous buyers. Its product has "},{"text":"no close substitutes","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Characteristics:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Mostly happens because of "},{"text":"economies of scale","bold":true},{"text":" advantages."}]},{"text":[{"text":"The firm is a "},{"text":"price maker","bold":true},{"text":" (unlike price takers in perfect competition)."}]},{"text":[{"text":"The firm creates "},{"text":"barriers to entry","bold":true},{"text":", making it difficult for others to enter."}]},{"text":[{"text":"Price discrimination","bold":true},{"text":" is common and a strategy."}]},{"text":[{"text":"The firm is a "},{"text":"profit maximiser","bold":true},{"text":"."}]},{"text":[{"text":"It often has access to "},{"text":"market intelligence or technology","bold":true},{"text":" that others cannot access, which puts it in a superior position."}]}]},{"type":"paragraph","text":[{"text":"Sources (causes) of monopoly:","bold":true},{"text":" economies of scale; "},{"text":"patent rights","bold":true},{"text":"; "},{"text":"ownership of a strategic raw material","bold":true},{"text":"; "},{"text":"government licensing","bold":true},{"text":"; a "},{"text":"market size that does not require more than one producer","bold":true},{"text":" (natural monopoly); exclusive technology or market intelligence."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Demand:","bold":true},{"text":" the monopolist faces the "},{"text":"downward-sloping","bold":true},{"text":" market demand curve: it can sell more only by lowering its price. AR = P."}]},{"text":[{"text":"MR is less than price","bold":true},{"text":", because to sell one more unit it must lower the price on "},{"text":"all","bold":true},{"text":" the units it sells."}]},{"text":[{"text":"Equilibrium:","bold":true},{"text":" output where "},{"text":"MR = MC","bold":true},{"text":"; price read off the demand curve at that output (P > MC)."}]},{"text":[{"text":"Long run:","bold":true},{"text":" the monopolist can keep "},{"text":"supernormal profit","bold":true},{"text":", because barriers to entry stop new firms competing it away."}]},{"text":[{"text":"Price discrimination:","bold":true},{"text":" selling the "},{"text":"same product at different prices to different buyers","bold":true},{"text":" for reasons not related to cost differences."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Conditions for price discrimination:","bold":true},{"text":" (1) the seller has price-making power; (2) the markets can be kept separate so buyers cannot resell; (3) demand elasticity differs between groups. The "},{"text":"higher price goes to the group with less elastic demand","bold":true},{"text":". "},{"text":"Degrees","bold":true},{"text":" (Pigou): first degree, each buyer pays the most he is willing to pay; second degree, price varies with quantity bought (bulk discounts); third degree, different prices for different groups (student fares, peak and off-peak airline fares, different electricity tariffs for homes and factories)."}]},{"text":[{"text":"Examples:","bold":true},{"text":" a firm holding a 20-year patent on a new drug is a monopoly from "},{"text":"patent rights","bold":true},{"text":". A small town that can support only one water-supply firm (laying pipes twice would never pay) is a "},{"text":"natural monopoly","bold":true},{"text":": market size and economies of scale. The old NEPA was a government-owned electricity monopoly created by law."}]},{"text":[{"text":"Compared with perfect competition, a monopoly charges a "},{"text":"higher price","bold":true},{"text":", produces a "},{"text":"lower output","bold":true},{"text":", is not allocatively efficient (P > MC) and need not produce at minimum ATC."}]},{"text":[{"text":"A monopolist never chooses output where MR is negative. TR is greatest where MR = 0, but profit is greatest where MR = MC."}]}]},{"type":"paragraph","text":[{"text":"Worked monopoly table.","bold":true},{"text":" Fixed cost ₦500. AR = P; TR = P × Q; MR = change in TR; TC = FC + sum of MCs so far."}]},{"type":"table","header":[[{"text":"Q"}],[{"text":"P (AR) ₦"}],[{"text":"TR ₦"}],[{"text":"MR ₦"}],[{"text":"MC ₦"}],[{"text":"TC ₦"}],[{"text":"Profit ₦"}]],"rows":[[[{"text":"1"}],[{"text":"1,000"}],[{"text":"1,000"}],[{"text":"1,000"}],[{"text":"300"}],[{"text":"800"}],[{"text":"200"}]],[[{"text":"2"}],[{"text":"850"}],[{"text":"1,700"}],[{"text":"700"}],[{"text":"250"}],[{"text":"1,050"}],[{"text":"650"}]],[[{"text":"3"}],[{"text":"700"}],[{"text":"2,100"}],[{"text":"400"}],[{"text":"300"}],[{"text":"1,350"}],[{"text":"750","bold":true}]],[[{"text":"4"}],[{"text":"550"}],[{"text":"2,200"}],[{"text":"100"}],[{"text":"350"}],[{"text":"1,700"}],[{"text":"500"}]],[[{"text":"5"}],[{"text":"400"}],[{"text":"2,000"}],[{"text":"−200"}],[{"text":"400"}],[{"text":"2,100"}],[{"text":"−100"}]],[[{"text":"6"}],[{"text":"250"}],[{"text":"1,500"}],[{"text":"−500"}],[{"text":"450"}],[{"text":"2,550"}],[{"text":"−1,050"}]]]},{"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua125', 33, $study_guide$type":"list","ordered":false,"items":[{"text":[{"text":"TR at 3 units = 700 × 3 = ₦2,100. MR of the 2nd unit = 1,700 − 1,000 = ₦700."}]},{"text":[{"text":"AR at 3 units = 2,100 ÷ 3 = ₦700 (always equals the price)."}]},{"text":[{"text":"TR is maximum at 4 units","bold":true},{"text":" (₦2,200; MR of the 5th is negative)."}]},{"text":[{"text":"Profit-maximising output:","bold":true},{"text":" MR ≥ MC for units 1 to 3 (3rd: 400 ≥ 300); the 4th has MR ₦100 < MC ₦350. So "},{"text":"3 units","bold":true},{"text":", at "},{"text":"price ₦700","bold":true},{"text":" (read from the demand schedule, not MR or MC)."}]},{"text":[{"text":"Maximum profit","bold":true},{"text":" = TR − TC = 2,100 − (500 + 300 + 250 + 300) = 2,100 − 1,350 = "},{"text":"₦750","bold":true},{"text":". The profit column confirms it."}]}]}]},{"number":"8.4","title":"Monopolistic competition","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Monopolistic competition:","bold":true},{"text":" an industry with a "},{"text":"large number of buyers and sellers","bold":true},{"text":" whose products are "},{"text":"differentiated but close substitutes","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Features:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Free entry and exit","bold":true},{"text":" of firms."}]},{"text":[{"text":"Firms aim at "},{"text":"profit maximisation","bold":true},{"text":" in both short and long run, which drives strategies like product differentiation, advertising, product quality and price."}]},{"text":[{"text":"Each firm has very limited power over the market price, because rivals offer many close substitutes."}]},{"text":[{"text":"Products are "},{"text":"substitutable, but not perfect substitutes","bold":true},{"text":"."}]},{"text":[{"text":"No firm has monopoly power","bold":true},{"text":"; where short-run supernormal profit appears, it "},{"text":"attracts more firms","bold":true},{"text":" into the market, which wipes away the profit."}]},{"text":[{"text":"Imperfect consumer knowledge","bold":true},{"text":" of the firms' brands."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Main difference from perfect competition:","bold":true},{"text":" products are "},{"text":"homogeneous","bold":true},{"text":" in perfect competition but "},{"text":"differentiated","bold":true},{"text":" in monopolistic competition."}]},{"text":[{"text":"Equilibrium:","bold":true},{"text":" MR = MC. "},{"text":"Short run:","bold":true},{"text":" supernormal profit possible. "},{"text":"Long run:","bold":true},{"text":" entry wipes it out, so firms earn "},{"text":"zero economic profit (only normal profit)","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Feature 3 is sometimes worded \"firms are price takers\", meaning no firm can push its price far from rivals' prices. Strictly, each firm faces a "},{"text":"downward-sloping","bold":true},{"text":" (very elastic) demand curve because its brand is a little different, so it can set its own price within a narrow range. In a choice between \"price taker\" and \"price maker\" for a monopolistic competitor, look at what the other options say; the \"price taker\" label belongs most firmly to perfect competition."}]},{"text":[{"text":"In the long run firms produce below the output of minimum ATC, so they operate with "},{"text":"excess capacity","bold":true},{"text":"; perfect competitors do not."}]},{"text":[{"text":"Examples:","bold":true},{"text":" dozens of hair salons on a Lagos street, each with slightly different styles and ambience, and new ones opening easily; restaurants, bukas, fashion designers, bakeries."}]},{"text":[{"text":"Edward Chamberlin (and Joan Robinson, as \"imperfect competition\") developed the theory in 1933."}]}]}]},{"number":"8.5","title":"Oligopoly and duopoly","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Oligopoly:","bold":true},{"text":" a market with a "},{"text":"small number of firms","bold":true},{"text":", none able to dominate the others, where all the firms have significant influence on market behaviour (a few firms account for most or all of industry output)."}]}]},{"type":"paragraph","text":[{"text":"Features of oligopoly:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Products are "},{"text":"homogeneous and substitutable; however, product differentiation also happens","bold":true},{"text":" (so products can be either homogeneous or differentiated)."}]},{"text":[{"text":"Small number","bold":true},{"text":" of producers."}]},{"text":[{"text":"High barriers to entry","bold":true},{"text":"."}]},{"text":[{"text":"Firms are "},{"text":"price setters","bold":true},{"text":"."}]},{"text":[{"text":"Firms are "},{"text":"interdependent","bold":true},{"text":": one firm's action affects the other firms (the key distinguishing feature)."}]},{"text":[{"text":"Each firm has its own "},{"text":"market share","bold":true},{"text":"."}]},{"text":[{"text":"Advertising","bold":true},{"text":" and other marketing are strategic."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Duopoly:","bold":true},{"text":" an industry dominated by "},{"text":"two firms","bold":true},{"text":" whose decisions affect each other. "},{"text":"Features:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"The two firms work together and interact in many decisions."}]},{"text":[{"text":"Entry barriers are lower, which allows another firm to enter."}]},{"text":[{"text":"Products are homogeneous."}]},{"text":[{"text":"Price competition is common because products are highly substitutable."}]},{"text":[{"text":"Quantity demanded of one firm's product depends on "},{"text":"its own price and the price charged by the rival","bold":true},{"text":"."}]},{"text":[{"text":"Firms are strategically interdependent."}]}]},{"type":"list","or$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua125', 34, $study_guide$dered":false,"items":[{"text":[{"text":"Equilibrium:","bold":true},{"text":" an oligopolist maximises profit where "},{"text":"MR = MC","bold":true},{"text":"."}]},{"text":[{"text":"Kinked demand curve","bold":true},{"text":" (Paul Sweezy, 1939): rivals "},{"text":"match price cuts but do not match price increases","bold":true},{"text":". Demand is elastic above the current price and inelastic below it, so there is a kink and a "},{"text":"gap in the MR curve","bold":true},{"text":"; MC can change within the gap without changing price. Result: prices are "},{"text":"relatively rigid (\"sticky\")","bold":true},{"text":" even when costs change."}]},{"text":[{"text":"Collusion:","bold":true},{"text":" an agreement among firms to fix prices and quantities. "},{"text":"Cartel:","bold":true},{"text":" a group of firms that comes together "},{"text":"formally","bold":true},{"text":" to make joint price and output decisions (OPEC, of which Nigeria is a member). Cartels arise most in "},{"text":"oligopoly","bold":true},{"text":"."}]},{"text":[{"text":"Collusive models:","bold":true},{"text":" cartel, joint profit maximisation, market-sharing cartel, price leadership (a dominant firm sets the price and others follow). "},{"text":"Non-collusive models:","bold":true},{"text":" the "},{"text":"kinked demand curve","bold":true},{"text":", Cournot (firms choose quantities), Bertrand (firms compete on price), Stackelberg (a leader chooses quantity first)."}]},{"text":[{"text":"Concentration ratio:","bold":true},{"text":" CRn = sum of the market shares of the n largest firms (or their sales ÷ total industry sales × 100). The higher it is, the fewer firms dominate."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Pure oligopoly:","bold":true},{"text":" few firms, "},{"text":"homogeneous","bold":true},{"text":" product (petroleum, cement, steel). "},{"text":"Differentiated oligopoly:","bold":true},{"text":" few firms, branded products (cars, telecom data plans)."}]},{"text":[{"text":"Nigerian examples:","bold":true},{"text":" mobile telecoms (MTN, Airtel, Glo), each spending heavily on advertising and quickly answering a rival's new data price; cement (Dangote, BUA, Lafarge Africa). Two firms supplying nearly all cooking gas cylinders in a state, each matching the other's price cuts, is a "},{"text":"duopoly","bold":true},{"text":"."}]},{"text":[{"text":"Output ranking:","bold":true},{"text":" oligopoly output is usually "},{"text":"higher than monopoly and lower than perfect competition","bold":true},{"text":". With identical products: collusion gives the lowest output (like a monopoly), Cournot more, Stackelberg more again, and "},{"text":"Bertrand price competition the highest","bold":true},{"text":" (price driven down towards MC, like perfect competition)."}]},{"text":[{"text":"Game theory","bold":true},{"text":" studies decisions when each player's result depends on rivals' choices; the prisoners' dilemma shows why cartel members are tempted to cheat."}]},{"text":[{"text":"Contestable markets","bold":true},{"text":" (William Baumol, 1982): if entry and exit are free and costless, the threat of entry forces even a few large firms to behave like "},{"text":"perfectly competitive firms","bold":true},{"text":" (normal profit only)."}]},{"text":[{"text":"Trap: \"complete absence of rivalry\" describes perfect competition, never oligopoly. \"Profit-maximising behaviour\" does not distinguish oligopoly; every structure maximises profit."}]}]},{"type":"paragraph","text":[{"text":"Worked concentration ratios:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Market shares of the six largest firms: 28%, 22%, 15%, 10%, 8%, 7%. CR4 = 28 + 22 + 15 + 10 = "},{"text":"75%","bold":true},{"text":" (ignore the 5th and 6th)."}]},{"text":[{"text":"Industry sales ₦800 million; four largest firms sell ₦200m, ₦160m, ₦100m, ₦60m. CR4 = (200 + 160 + 100 + 60) ÷ 800 × 100 = 520 ÷ 800 × 100 = "},{"text":"65%","bold":true},{"text":"."}]},{"text":[{"text":"As a rough guide: a high ratio for a few firms points to oligopoly; two firms holding most of the market (for example CR2 near 90%) points to a duopoly-like market; one firm near 100% is monopoly; a low ratio spread over many firms points to perfect or monopolistic competition."}]}]}]},{"number":"8.6","title":"Monopsony, duopsony and comparing structures","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Monopsony:","bold":true},{"text":" a market with a "},{"text":"single buyer","bold":true},{"text":" of products supplied by numerous suppliers. "},{"text":"Features:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Barriers to entry into the market."}]},{"text":[{"text":"Only "},{"text":"one buyer","bold":true},{"text":" of the goods produced; no other buyers."}]},{"text":[{"text":"The single buyer has "},{"text":"huge power","bold":true},{"text":" over prices and quantities produced."}]},{"text":[{"text":"Low prices","bold":true},{"text":" for suppliers (they have low bargaining power)."}]},{"text":[{"text":"Causes:","bold":true},{"text":" government regulations, geographical location, unique consumption behaviour, and unregulated "},{"text":"mergers and acquisitions","bold":true},{"text":"."}]},{"text":[{"text":"Low innovation and market inefficiency","bold":true},{"text":", because competition is low."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Duopsony:","bold":true},{"text":" a market with "},{"text":"two large firms","bold":true},{"text":" buying the goods and services of many producers. "},{"text":"Features:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"The two firms determine market demand."}]},{"text":[{"text":"They enjoy great bargaining power."}]},{"text":[{"text":"Less competition and higher profit."}]},{"text":[{"text":"High barriers to entry","bold":true},{"text":"."}]}]},{"type":"table",$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua125', 35, $study_guide$"header":[[{"text":"Structure"}],[{"text":"Firms"}],[{"text":"Product"}],[{"text":"Entry"}],[{"text":"Power over price"}],[{"text":"Long-run profit"}]],"rows":[[[{"text":"Perfect competition"}],[{"text":"very many"}],[{"text":"homogeneous"}],[{"text":"free"}],[{"text":"none (price taker)"}],[{"text":"normal only"}]],[[{"text":"Monopolistic competition"}],[{"text":"many"}],[{"text":"differentiated, close substitutes"}],[{"text":"free"}],[{"text":"slight"}],[{"text":"normal only"}]],[[{"text":"Oligopoly"}],[{"text":"few"}],[{"text":"homogeneous or differentiated"}],[{"text":"high barriers"}],[{"text":"price setter, interdependent"}],[{"text":"can be supernormal"}]],[[{"text":"Duopoly"}],[{"text":"two"}],[{"text":"homogeneous"}],[{"text":"lower barriers"}],[{"text":"interdependent"}],[{"text":"can be supernormal"}]],[[{"text":"Monopoly"}],[{"text":"one seller"}],[{"text":"no close substitute"}],[{"text":"blocked"}],[{"text":"price maker"}],[{"text":"supernormal"}]],[[{"text":"Monopsony"}],[{"text":"one buyer"}],[{"text":"many suppliers"}],[{"text":"barriers"}],[{"text":"buyer sets low prices"}],[{"text":"buyer gains"}]],[[{"text":"Duopsony"}],[{"text":"two buyers"}],[{"text":"many suppliers"}],[{"text":"high barriers"}],[{"text":"buyers dominate"}],[{"text":"higher profit"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Memory trick:","bold":true},{"text":" \"-poly\" = sellers, \"-psony\" = buyers. Monopoly = one seller; monopsony = one buyer. Duopoly = two sellers; duopsony = two buyers."}]},{"text":[{"text":"Examples:","bold":true},{"text":" in a remote mining town where one company is the only employer and workers have no other job options, the labour market is a "},{"text":"monopsony","bold":true},{"text":". Thousands of cocoa farmers who can sell only to two large processing companies, which together set how much is bought and at what price, face a "},{"text":"duopsony","bold":true},{"text":". Nigeria's old commodity marketing boards (abolished in 1986) were the only legal buyers of export crops like cocoa: a monopsony created by government regulation."}]},{"text":[{"text":"A large number of competing buyers is the opposite of monopsony, never a cause of it."}]},{"text":[{"text":"Implications for managers:","bold":true},{"text":" know your structure before pricing. A price taker controls only output and cost; a monopolist or oligopolist must weigh price, rivals' reactions and regulators; a monopolistic competitor must keep differentiating, because profits attract entrants."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Market structure = classification of industries by the degree and nature of competition; 7 types; classified mainly by number of firms and product differentiation."}]},{"text":[{"text":"Every firm maximises profit at "},{"text":"MR = MC","bold":true},{"text":"; profit = (P − ATC) × Q; normal profit = zero economic profit."}]},{"text":[{"text":"Perfect competition: many firms, homogeneous product, free entry, price takers, horizontal demand, P = MR; shut down if P < AVC; long run P = MC = min ATC, normal profit, both efficiencies."}]},{"text":[{"text":"Monopoly: one seller, no close substitutes, price maker, barriers (scale, patent, raw material, licence, small market), MR < P, keeps supernormal profit, price discrimination."}]},{"text":[{"text":"Monopolistic competition: many firms, differentiated close substitutes, free entry, normal profit in the long run, excess capacity."}]},{"text":[{"text":"Oligopoly: few firms, interdependence, high barriers, price setters; kinked demand gives sticky prices; collusion and cartels."}]},{"text":[{"text":"Duopoly: two firms; demand depends on own and rival's price."}]},{"text":[{"text":"Monopsony = one buyer (low supplier prices, low innovation); duopsony = two buyers (high barriers, great bargaining power)."}]},{"text":[{"text":"CRn = sum of the n largest market shares."}]}]}],"theory":{"itemId":"5d65ec8b-d2fe-516b-8e5e-90e1b712669f","question":[{"type":"paragraph","text":[{"text":"A perfectly competitive firm produces 800 units where MR = MC. The market price is ₦250, its ATC is ₦290 and its AVC is ₦230. Find its profit or loss and say whether it should keep producing in the short run."}]}]},"practice":[{"topic":"Market Structure","named":false}]}}],"theory":[{"kind":"theory_question","itemId":"e310cac9-bb61-5215-81d6-0a503d9c8621","sourceKey":"guide-theory:1","position":1,"payload":{"prompt":"A firm expects profits of ₦8m, ₦9m and ₦10m at the end of years 1, 2 and 3. Using a 12% discount rate (compounded annually), find the value of the firm to 2 decimal places."},"answer":{"kind":"model_answer","itemId":"cd022cc0-bfb4-5740-9a65-e86f5ef9209e","sourceKey":"guide-answer:1","payload":{"body":"• Year 1: 8 / 1.12 = ₦7.1429m.\n• Year 2: 9 / 1.12^2 = 9 / 1.2544 = ₦7.1747m.\n• Year 3: 10 / 1.12^3 = 10 / 1.404928 = ₦7.1178m.\n• Value = 7.1429 + 7.1747 + 7.1178 = ₦21.44m (rounded to 2 d.p.), well below the undiscounted ₦27m."}}},{"kind":"theory_question","itemId":"05c9ca48-cb8f-5ac6-a10d-bd84f49d7fe2","sourceKey":"guide-theory:2","position":2,"payload":{"prompt":"Funke earns revenue of ₦10,000,000 from her catering firm. Explicit costs are ₦6,500,000. She gave up a salary of ₦1,500,000 and put in ₦4,000,000 of her own savings that could earn 12% a year. Find her accounting profit and economic profit."},"answer":{"kind":"model_answer","itemId":"79695942-a7dd-5cb7-a2d9-fd732b74dedd","sourceKey":"guide-answer:2","payload":{"body":"• Accounting profit = 10,000,000 − 6,500,000 = ₦3,500,000.\n• Implicit costs = 1,500,000 + (4,000,000 × 0.12 = 480,000) = ₦1,980,000.\n• Economic profit = 3,500,000 − 1,980,000 = ₦1,520,000, an above-normal profit: catering beats her best alternative."}}},{"kind":"theory_question","itemId":"4bd3c121-03a7-5136-8083-ef24dea93d88","sourceKey":"guide-theory:3","position":3,"payload":{"prompt":"A Surulere kiosk cuts the price of a chilled drink from ₦500 to ₦400,$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua125', 36, $study_guide$ and daily sales rise from 200 to 300 bottles. Using the midpoint method, find the price elasticity of demand, classify it, and state what happened to total revenue."},"answer":{"kind":"model_answer","itemId":"6a0bceb7-ee10-5f73-976c-05bd972459a1","sourceKey":"guide-answer:3","payload":{"body":"• %ΔQ = (300 - 200) / [(200 + 300)/2] = 100 / 250 = 40%.\n• %ΔP = (400 - 500) / [(500 + 400)/2] = -100 / 450 = -22.22%.\n• PED = 40 / 22.22 = 1.8 in absolute value: elastic.\n• TR before = ₦500 x 200 = ₦100,000; TR after = ₦400 x 300 = ₦120,000. Revenue rose by ₦20,000, as expected when price is cut on elastic demand."}}},{"kind":"theory_question","itemId":"ef914fd9-9610-5ce7-b1de-3f701eff4930","sourceKey":"guide-theory:4","position":4,"payload":{"prompt":"A Kano rice seller sold 60, 64, 70, 66 and 72 bags in weeks 1 to 5. Find the 4-week simple moving average forecast for week 6. Then, using exponential smoothing with alpha = 0.5 and a week-5 forecast of 68 bags, find the week-6 forecast."},"answer":{"kind":"model_answer","itemId":"fa504d69-82e5-5472-80e3-3bcdb772b02e","sourceKey":"guide-answer:4","payload":{"body":"Moving average uses weeks 2 to 5: (64 + 70 + 66 + 72) / 4 = 272 / 4 = 68.00 bags. Exponential smoothing: F6 = 68 + 0.5 x (72 - 68) = 68 + 2 = 70 bags. The smoothing forecast is higher because it gives half the weight to the latest (high) week."}}},{"kind":"theory_question","itemId":"00a2f083-5476-5812-9189-babd4a5c029c","sourceKey":"guide-theory:5","position":5,"payload":{"prompt":"A firm's TFC is ₦200. Its TVC at 1, 2, 3 and 4 units is ₦80, ₦140, ₦210 and ₦320. Find AVC, ATC and MC at each output, and the lowest price at which a price-taking firm would keep producing in the short run."},"answer":{"kind":"model_answer","itemId":"16019f53-9e16-5e7d-9f40-0810c41cea93","sourceKey":"guide-answer:5","payload":{"body":"Q | TVC (₦) | AVC = TVC/Q (₦) | ATC = (200 + TVC)/Q (₦) | MC (₦)\n1 | 80 | 80 | 280 | 80\n2 | 140 | 70 | 170 | 60\n3 | 210 | 70 | 136.67 | 70\n4 | 320 | 80 | 130 | 110\n(ATC at 3 rounded to 2 decimal places.) Minimum AVC is ₦70 (at 2 and 3 units), so the shut-down price is ₦70: below it, revenue would not cover variable cost. Note that MC of the 3rd unit (₦70) equals AVC at its minimum."}}},{"kind":"theory_question","itemId":"676cac5a-37f5-5f0d-a8da-ac1420773b8b","sourceKey":"guide-theory:6","position":6,"payload":{"prompt":"A snack firm with a small budget compares two campus segments. Segment A: 30,000 students, 20% interested, each spending ₦4,000 a month. Segment B: 8,000 staff, 50% interested, each spending ₦5,000 a month. Find each segment's monthly value and name the targeting strategy if the firm serves only the better one."},"answer":{"kind":"model_answer","itemId":"d7d0ec6f-fd38-5a62-8321-ffa9004bc8dc","sourceKey":"guide-answer:6","payload":{"body":"A buyers = 30,000 x 0.20 = 6,000; value = 6,000 x ₦4,000 = ₦24,000,000. B buyers = 8,000 x 0.50 = 4,000; value = 4,000 x ₦5,000 = ₦20,000,000. Segment A is worth more, so a firm with limited resources serving only A is using concentrated (niche) marketing."}}},{"kind":"theory_question","itemId":"060f6630-377b-5ee1-a865-be44efa268f4","sourceKey":"guide-theory:7","position":7,"payload":{"prompt":"State three differences between a private limited company and a public limited company, and one feature they share."},"answer":{"kind":"model_answer","itemId":"de6b39e2-ae09-5232-b202-abe5c57469fd","sourceKey":"guide-answer:7","payload":{"body":"(1) A Plc can invite the general public to buy its shares; an Ltd cannot. (2) An Ltd restricts the transfer of its shares; a Plc's shares are freely transferable and may be listed on the Nigerian Exchange. (3) Under CAMA 2020 an Ltd has 1 to 50 members, while a Plc needs at least 2 and has no maximum; a Plc must also publish more financial information. Shared feature: both give shareholders limited liability (and both are separate legal entities with perpetual succession, registered by the CAC)."}}},{"kind":"theory_question","itemId":"5d65ec8b-d2fe-516b-8e5e-90e1b712669f","sourceKey":"guide-theory:8","position":8,"payload":{"prompt":"A perfectly competitive firm produces 800 units where MR = MC. The market price is ₦250, its ATC is ₦290 and its AVC is ₦230. Find its profit or loss and say whether it should keep producing in the short run."},"answer":{"kind":"model_answer","itemId":"fa46f1e0-5a0c-5e33-bf72-212283d8d86d","sourceKey":"guide-answer:8","payload":{"body":"Loss = (P − ATC) × Q = (250 − 290) × 800 = −₦32,000. Since P (₦250) is above AVC (₦230), it should keep producing. If it shut down it would lose its whole fixed cost: AFC = 290 − 230 = ₦60, so FC = 60 × 800 = ₦48,000. Producing keeps the loss ₦16,000 smaller."}}}]}$study_guide$);
